INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('a627df4e-f241-478e-b8ab-273e67f52441'::uuid, 'card_description', 'Oak planks laid end-to-end on crossed pegs of ash, oak and lime: the Sweet Track, built in 3807 or 3806 BC across a Somerset marsh, was used for only around ten years, then abandoned.', 'Timber causeway built in 3807 BC across the Somerset Levels—dendrochronology dated it to the exact year. The second-oldest timber trackway of its type found in the islands.', 'teaser-card-s010-rollback:a627df4e-f241-478e-b8ab-273e67f52441:card_description', 'rollback of teaser-card-s010: card_description ''Timber causeway built in 3807 BC across the Somerset Levels—dendrochronology dated it to the exact year. The second-oldest timber trackway of its type found in the islands.'' restored on Sweet Track', '9f030a0951c91866bccda4f2463bac9c66cfea09215d5feabba5b7da228a453d|451eb72c31a0645d15eb25a841c18c60c93f755ff431f048081eceea180298b0|451eb72c31a0645d15eb25a841c18c60c93f755ff431f048081eceea180298b0', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Oak planks laid end-to-end on crossed pegs of ash, oak and lime: the Sweet Track, built in 3807 or 3806 BC across a Somerset marsh, was used for only around ten years, then abandoned."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the track is called the Sweet Track [S1]; the track''s walkway consisted of oak planks laid end-to-end [S7]; the planks were supported by crossed pegs of ash, oak and lime [S7]; the track was built in 3807 or 3806 BC [S7]; the track lay across a marsh in Somerset [S1, S3]; the track was used for only around ten years [S5]; the track was then abandoned [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Sweet Track is an ancient timber trackway (causeway), the kind of place the text describes, in the Somerset Levels, England [SUPPORTED: https://en.wikipedia.org/wiki/Sweet_Track]; The track ran across a marsh in Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Sweet_Track]; The walkway consisted of oak planks laid end-to-end [SUPPORTED: https://en.wikipedia.org/wiki/Sweet_Track]; The planks were supported by crossed pegs of ash, oak and lime [SUPPORTED: https://en.wikipedia.org/wiki/Sweet_Track]; The track was built in 3807 or 3806 BC [SUPPORTED: https://www.worldhistory.org/The_Sweet_Track/]; The track was used for only around ten years [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=504]; After those ten years the track was abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Sweet_Track]"}]'::jsonb),
    ('a692e959-c6b4-45b5-96f6-65b82c883a35'::uuid, 'card_description', NULL, 'A Roman Danubian fort (134 x 126 m) in the Moesian Limes frontier system. Its walls were upgraded from wood to stone before Domitian''s Dacian War in 87 AD.', 'teaser-card-s010-rollback:a692e959-c6b4-45b5-96f6-65b82c883a35:card_description', 'rollback of teaser-card-s010: card_description "A Roman Danubian fort (134 x 126 m) in the Moesian Limes frontier system. Its walls were upgraded from wood to stone before Domitian''s Dacian War in 87 AD." restored on Taliata', '||d6f1d857d95fd2264ccbd1722a5cdbf7a31c28b25cac94f3485743c2d16a9792', '[{"source": "lane WB run wb-ws-2026-09-27-04: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The web check could not prove: It was Domitian who replaced the fort''s wood-and-earth walls with stone walls (English Wikipedia says so without a citation, its sister article Moesian Limes tags the same sentence citation needed, and Serbian Wikipedia dates the stone castellum to the 2nd century after Trajan''s Dacian wars, preceded by a 1st-century earthen fort); The web check could not prove: The stone walls were built in 87 AD (no citable page settles the year; see the previous claim); The web check could not prove: Taliata is a Roman fort (and town) near Donji Milanovac in Serbia"}]'::jsonb),
    ('a6d5b07a-c9ea-4e5a-a82d-4416a045f1bc'::uuid, 'card_description', 'Between Tjörnarp and Sösdala lies the Vätteryd Grave Field, an Iron Age burial ground that gave up bronze jewelry, glass and bronze pearls, silver threads and silver bands.', 'This Scanian grave field holds 183 menhirs, 15 stone ships — the largest 25 meters long and 8 meters wide — and 2 circles, dating 400–900 AD. Few sites in Scandinavia match this monument density.', 'teaser-card-s010-rollback:a6d5b07a-c9ea-4e5a-a82d-4416a045f1bc:card_description', 'rollback of teaser-card-s010: card_description ''This Scanian grave field holds 183 menhirs, 15 stone ships — the largest 25 meters long and 8 meters wide — and 2 circles, dating 400–900 AD. Few sites in Scandinavia match this monument density.'' restored on Vätteryd Grave Field', 'f29ebe5453180e70e4cd101ba4f442f41999b83dbeb026947fd66226dec519a7|dfd7fd887f3b7e6af51b55bd02223499d5a65ed7b70c09341403b582e28ccd7b|dfd7fd887f3b7e6af51b55bd02223499d5a65ed7b70c09341403b582e28ccd7b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Between Tjörnarp and Sösdala lies the Vätteryd Grave Field, an Iron Age burial ground that gave up bronze jewelry, glass and bronze pearls, silver threads and silver bands."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the grave field lies between Tjörnarp and Sösdala [S2]; it is an Iron Age burial ground [S1, S3]; bronze jewelry was found [S4]; glass and bronze pearls were found [S4]; silver threads and silver bands were found [W1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Vätteryd Grave Field is an Iron Age burial ground (grave field) in Scania, Sweden [SUPPORTED: https://en.wikipedia.org/wiki/V%C3%A4tteryd]; The grave field lies between Tjörnarp and Sösdala [SUPPORTED: https://en.wikipedia.org/wiki/V%C3%A4tteryd]; The grave field yielded bronze jewelry [SUPPORTED: https://en.wikipedia.org/wiki/V%C3%A4tteryd]; The grave field yielded glass and bronze pearls [SUPPORTED: https://en.wikipedia.org/wiki/V%C3%A4tteryd]; The grave field yielded silver threads and silver bands [SUPPORTED: https://sv.wikipedia.org/wiki/V%C3%A4tteryds_gravf%C3%A4lt]"}, {"source": "web fact W1", "url": "https://sv.wikipedia.org/wiki/V%C3%A4tteryds_gravf%C3%A4lt", "quote": "sländor, skärvor samt silvertrådar och silverband"}]'::jsonb),
    ('a6f66111-c0d1-4c01-a49a-eb2d476a33d0'::uuid, 'card_description', 'Built from the booty of battles against Athens, the Treasury of the Acanthians rose at Delphi. Plutarch records its dedication: Brasidas and the Acanthians from the Athenians.', '5th-century BC treasury at Delphi, built by Acanthos to commemorate its joint victory with the Lacedaemonians against Athens. A monument to the moment one city switched sides in the Peloponnesian War.', 'teaser-card-s010-rollback:a6f66111-c0d1-4c01-a49a-eb2d476a33d0:card_description', 'rollback of teaser-card-s010: card_description ''5th-century BC treasury at Delphi, built by Acanthos to commemorate its joint victory with the Lacedaemonians against Athens. A monument to the moment one city switched sides in the Peloponnesian War.'' restored on Treasury of the Acanthians', '36262152b044a2112dc31e2862d16175658bf6b3cf54c6066897e51eb0e4a507|215da1b96111a0fbe84e8cc42b28c20ae85c2299947c48221ca20567c2892024|215da1b96111a0fbe84e8cc42b28c20ae85c2299947c48221ca20567c2892024', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Built from the booty of battles against Athens, the Treasury of the Acanthians rose at Delphi. Plutarch records its dedication: Brasidas and the Acanthians from the Athenians."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Treasury of the Acanthians stood at Delphi [S1, S4]; it was built from the booty of battles [S4]; the battles were fought against Athens [S1, S3, S5]; Plutarch mentions its dedicatory inscription [S5]; the inscription reads: Brasidas and the Acanthians from the Athenians [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Treasury of the Acanthians is a treasury building in the sanctuary at Delphi, Greece, the kind of place the text describes [SUPPORTED: https://en.wikipedia.org/wiki/Treasury_of_the_Acanthians]; It was built by the Acanthians, the citizens of Acanthos [SUPPORTED: https://en.wikipedia.org/wiki/Treasury_of_the_Acanthians]; It was built from the booty (spoil) of battles [SUPPORTED: https://en.wikipedia.org/wiki/Treasury_of_the_Acanthians]; The battles were fought against Athens [SUPPORTED: https://en.wikipedia.org/wiki/Treasury_of_the_Acanthians]; Plutarch records the dedication of the treasury [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Plutarch/Lives/Lysander*.html]; The dedication reads: Brasidas and the Acanthians from the Athenians [SUPPORTED: https://en.wikipedia.org/wiki/Treasury_of_the_Acanthians]"}]'::jsonb),
    ('a7afa2f1-87c5-4fa8-ab8f-0e86d714a8f8'::uuid, 'card_description', 'On the west side of the Fosse Way lies Dorn, where a small Roman town once stood: the largest of five defended small towns strung along its line between Cirencester and Lincoln.', 'A small Roman town on the Fosse Way — the largest of five defended towns on that road. It was forgotten entirely until modern archaeology revealed it.', 'teaser-card-s010-rollback:a7afa2f1-87c5-4fa8-ab8f-0e86d714a8f8:card_description', 'rollback of teaser-card-s010: card_description ''A small Roman town on the Fosse Way — the largest of five defended towns on that road. It was forgotten entirely until modern archaeology revealed it.'' restored on Dorn, Gloucestershire', '282702ccf43e1b3e7077275d693eb0dde731a195d70f53378633a0baa7f475ff|9cc63608e44a7f4fe907a26aa376e46cc0e1921da0d9b2a2fac0058d912492ef|9cc63608e44a7f4fe907a26aa376e46cc0e1921da0d9b2a2fac0058d912492ef', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the west side of the Fosse Way lies Dorn, where a small Roman town once stood: the largest of five defended small towns strung along its line between Cirencester and Lincoln."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dorn lies on the west side of the Fosse Way [S1]; a small Roman town once stood at Dorn [S1]; the Roman site was the largest of five defended small towns [S2]; the five small towns lay along the line of the Fosse Way between Cirencester and Lincoln [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dorn, Gloucestershire, is the site of a small Roman town [SUPPORTED: https://en.wikipedia.org/wiki/Dorn,_Gloucestershire]; The Roman site lies on the west side of the Fosse Way [SUPPORTED: https://www.roman-britain.co.uk/places/dorn/]; The town was defended (bank and ditch) [SUPPORTED: https://www.roman-britain.co.uk/places/dorn/]; It was the largest of five defended small towns on the line of the Fosse Way between Cirencester and Lincoln [SUPPORTED: https://en.wikipedia.org/wiki/Dorn,_Gloucestershire]"}]'::jsonb),
    ('a7ce791d-67cb-4895-bb89-00d4f1dd868b'::uuid, 'card_description', 'In a valley near Taxila, the Buddhist monastery of Mohra Muradu set 27 rooms around a courtyard with a pool for ritual washings, and statues of Buddha were found there in abundance.', 'A 2nd-century Buddhist monastery near Taxila where monks lived close enough to the city to beg for food but remote enough for silent meditation. Carved stone heads of the Buddha were found here.', 'teaser-card-s010-rollback:a7ce791d-67cb-4895-bb89-00d4f1dd868b:card_description', 'rollback of teaser-card-s010: card_description ''A 2nd-century Buddhist monastery near Taxila where monks lived close enough to the city to beg for food but remote enough for silent meditation. Carved stone heads of the Buddha were found here.'' restored on Mohra Muradu', 'ce78543c2cfff347f0f6bba7af156162eeb46ea6d27e3fdb490e58d02a0730a3|dfe1aae553493dda11411199ebd84eb634bb568a3b16bd1413e6030c3ab3bdc0|dfe1aae553493dda11411199ebd84eb634bb568a3b16bd1413e6030c3ab3bdc0', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In a valley near Taxila, the Buddhist monastery of Mohra Muradu set 27 rooms around a courtyard with a pool for ritual washings, and statues of Buddha were found there in abundance."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies in a valley [S2]; the site lies near Taxila [S1]; Mohra Muradu is a Buddhist monastery [S1, S4]; the monastery has 27 rooms [S6]; the rooms are built around a courtyard with a pool [S6]; the pool held water for ritual washings [S7]; statues of Buddha were found there in abundance [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mohra Muradu is a Buddhist monastery (with stupas) near the ruins of Taxila, Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; The monastery lies in a valley [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; The monastery has 27 rooms [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; The rooms are set around a courtyard [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; The courtyard has a pool [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; The pool in the courtyard held water for ritual washings [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; Statues of Buddha were found there [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; The Buddha statues were found in abundance [SUPPORTED: https://en.wikipedia.org/wiki/Mohra_Muradu]; The Mohra Moradu monastic remains are one of the Buddhist archaeological sites of the Taxila valley (UNESCO) [SUPPORTED, no proving quote: https://whc.unesco.org/en/list/139]"}]'::jsonb),
    ('a9a3d2fe-0f58-4627-a34d-124e0190d7e8'::uuid, 'card_description', 'Named for the many bats in the caves of nearby cliffs, the Maya site of El Zotz appears to have peaked for only about one hundred years, in an intense burst of building palaces and pyramids.', 'A Maya city 20 km from Tikal with a 45-metre temple crowned by a massive stucco sun-god mask. The mask was painted blood-red and once blazed in the sunset light.', 'teaser-card-s010-rollback:a9a3d2fe-0f58-4627-a34d-124e0190d7e8:card_description', 'rollback of teaser-card-s010: card_description ''A Maya city 20 km from Tikal with a 45-metre temple crowned by a massive stucco sun-god mask. The mask was painted blood-red and once blazed in the sunset light.'' restored on El Zotz', '2fbf406312f96245b1108df5ecc58608fd343d26a4b344b7532aac9241a92fe7|0e65467adff44bec02abba3d59bc812509c39418291d1776c548078f97c60b3d|0e65467adff44bec02abba3d59bc812509c39418291d1776c548078f97c60b3d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Named for the many bats in the caves of nearby cliffs, the Maya site of El Zotz appears to have peaked for only about one hundred years, in an intense burst of building palaces and pyramids."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "El Zotz is named for the large number of bats in caves of nearby cliffs [S2]; El Zotz is a Maya site [S1]; El Zotz appears to have peaked for only about one hundred years [S3]; the peak was an intense burst of construction [S3]; the building included palaces and pyramids [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "El Zotz is a Maya archaeological site (in Guatemala) [SUPPORTED: https://en.wikipedia.org/wiki/El_Zotz]; El Zotz is named for the many bats [SUPPORTED: https://en.wikipedia.org/wiki/El_Zotz]; The bats live in caves in the cliffs near the site [SUPPORTED: https://en.wikipedia.org/wiki/El_Zotz]; The apogee of El Zotz appears to have lasted only about one hundred years [SUPPORTED: https://en.wikipedia.org/wiki/El_Zotz]; During the apogee there was an intense burst of construction activity [SUPPORTED: https://en.wikipedia.org/wiki/El_Zotz]; The construction burst included palaces and pyramids [SUPPORTED: https://en.wikipedia.org/wiki/El_Zotz]"}]'::jsonb),
    ('aaa12d23-d666-4a40-9f3c-17d861f4e143'::uuid, 'card_description', 'Lance-bearers, ritual dances, camel caravans, the sun and other stars: quarry workers stumbled on the Gobustan Rock Art in the 1930s, engravings from prehistoric to medieval times.', 'The Gobustan Rock Art Cultural Landscape reflects the history of human development in Eurasia from the Upper Paleolithic era through the Middle Ages.', 'teaser-card-s010-rollback:aaa12d23-d666-4a40-9f3c-17d861f4e143:card_description', 'rollback of teaser-card-s010: card_description ''The Gobustan Rock Art Cultural Landscape reflects the history of human development in Eurasia from the Upper Paleolithic era through the Middle Ages.'' restored on Gobustan Rock Art', 'b4660ceadd72cafe490c8dfa3608297ed04d05371ba120f9524d45e44f180700|9a89f46b1cf4868042882cf57d0e94e2c030c56dcaa265d91c0ac2b0b5c71f4e|9a89f46b1cf4868042882cf57d0e94e2c030c56dcaa265d91c0ac2b0b5c71f4e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Lance-bearers, ritual dances, camel caravans, the sun and other stars: quarry workers stumbled on the Gobustan Rock Art in the 1930s, engravings from prehistoric to medieval times."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the rock art depicts lance-bearers [S2]; the rock art depicts ritual dances [S2]; the rock art depicts camel caravans [S2]; the rock art depicts the sun and other stars [S2]; quarry workers accidentally discovered the rock art [S5]; the discovery was in the 1930s [S5]; the engravings date from prehistoric to medieval times [S1, S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Gobustan Rock Art is a site of prehistoric-to-medieval rock engravings (petroglyphs) in Azerbaijan [SUPPORTED: https://en.wikipedia.org/wiki/Gobustan_Rock_Art_Cultural_Landscape]; The engravings show lance-bearers and ritual dance scenes [SUPPORTED: https://en.wikipedia.org/wiki/Gobustan_Rock_Art_Cultural_Landscape]; The engravings show camel caravans [SUPPORTED: https://en.wikipedia.org/wiki/Gobustan_Rock_Art_Cultural_Landscape]; The engravings show the sun and other stars [SUPPORTED: https://en.wikipedia.org/wiki/Gobustan_Rock_Art_Cultural_Landscape]; The rock art was discovered by quarry workers in the 1930s [SUPPORTED: https://en.wikipedia.org/wiki/Gobustan_Rock_Art_Cultural_Landscape]; The engravings date from prehistoric to medieval times [SUPPORTED: https://en.wikipedia.org/wiki/Gobustan_Rock_Art_Cultural_Landscape]; The site shows human use from the Upper Paleolithic to the Middle Ages (UNESCO) [SUPPORTED, no proving quote: https://whc.unesco.org/en/list/1076]"}]'::jsonb),
    ('ab20e4ad-f101-4b3d-84fb-c0710060c941'::uuid, 'card_description', 'Outside the entrance of the Stonehenge earthwork, the Heel Stone, a single sarsen weighing about 35 tons, leans nearly 27 degrees from the vertical, with a further 1.2 metres buried below.', 'A massive sarsen stone standing 4.7 metres high outside the Stonehenge earthwork, leaning nearly 27 degrees to the southwest. It aligns with the midsummer sunrise.', 'teaser-card-s010-rollback:ab20e4ad-f101-4b3d-84fb-c0710060c941:card_description', 'rollback of teaser-card-s010: card_description ''A massive sarsen stone standing 4.7 metres high outside the Stonehenge earthwork, leaning nearly 27 degrees to the southwest. It aligns with the midsummer sunrise.'' restored on Heel Stone', '07099af8fbad37a811a4f156946be66e697700c145f5b41b0760be8315bce314|9ea724b35e4f59e788276bdc6350319d40ae79e3bf12225df53fca0d2be44321|9ea724b35e4f59e788276bdc6350319d40ae79e3bf12225df53fca0d2be44321', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Outside the entrance of the Stonehenge earthwork, the Heel Stone, a single sarsen weighing about 35 tons, leans nearly 27 degrees from the vertical, with a further 1.2 metres buried below."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Heel Stone stands outside the entrance of the Stonehenge earthwork [S1]; it is a single sarsen [S1]; it weighs about 35 tons [S6]; it leans nearly 27 degrees from the vertical [S5]; a further 1.2 metres of it is buried in the ground [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Heel Stone is a single block of sarsen stone [SUPPORTED: https://en.wikipedia.org/wiki/Heel_Stone]; The Heel Stone stands outside the entrance of the Stonehenge earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Heel_Stone]; The Heel Stone weighs about 35 tons [SUPPORTED: https://en.wikipedia.org/wiki/Heel_Stone]; The Heel Stone leans nearly 27 degrees from the vertical [SUPPORTED: https://en.wikipedia.org/wiki/Heel_Stone]; A further 1.2 metres of the Heel Stone is buried in the ground [SUPPORTED: https://en.wikipedia.org/wiki/Heel_Stone]"}]'::jsonb),
    ('ab524e5e-2c34-4564-ab3a-f7ab487116f4'::uuid, 'card_description', 'In 1932 a collapse during the renovation of homes in Minori opened an underground chamber of the Villa Romana, a Roman villa of the 1st century on a bay where the Regina Minor meets the sea.', 'A 1st-century AD Roman villa on the Amalfi Coast, where aristocrats built seaside residences. Its remains sit at the point where the Regina Minor river meets the sea.', 'teaser-card-s010-rollback:ab524e5e-2c34-4564-ab3a-f7ab487116f4:card_description', 'rollback of teaser-card-s010: card_description ''A 1st-century AD Roman villa on the Amalfi Coast, where aristocrats built seaside residences. Its remains sit at the point where the Regina Minor river meets the sea.'' restored on Villa Romana, Minori', '704b3bb80cacb164c20264cc34cb2593188a7a7c545aa483223bda39d06705c5|291459d5d10c0783f3bb6462b759329c7c928f1364dafa002298877290e5fb3c|291459d5d10c0783f3bb6462b759329c7c928f1364dafa002298877290e5fb3c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In 1932 a collapse during the renovation of homes in Minori opened an underground chamber of the Villa Romana, a Roman villa of the 1st century on a bay where the Regina Minor meets the sea."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "in 1932 a collapse occurred [S4]; the collapse happened during the renovation of homes in Minori [S1, S4]; the collapse led to the discovery of an underground chamber of the Villa Romana [S4]; the villa is a Roman villa of the 1st century [S1]; the villa stood on a bay [S2]; the river Regina Minor meets the sea at that bay [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Villa Romana is a Roman villa (archaeological site) in Minori, Campania, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Romana,_Minori]; The villa dates from the 1st century [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Romana,_Minori]; The villa stood in a bay [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Romana,_Minori]; The bay is where the river Regina Minor meets the sea [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Romana,_Minori]; In 1932 a collapse occurred during the renovation of local homes [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Romana,_Minori]; The collapse led to the discovery of an underground chamber of the villa [SUPPORTED: https://en.wikipedia.org/wiki/Villa_Romana,_Minori]"}]'::jsonb),
    ('ab6ffb1d-c6d2-4c14-96e8-7f76a2607d7d'::uuid, 'card_description', 'On the north coast of Crete, Amnisos was a Bronze Age port to the palace city of Knossos. The sea now stands three meters higher, and walls of submerged houses can be seen from the shore.', 'A Minoan port city from the 2nd millennium BC that served as the harbor for Knossos. Homer mentioned it in the Odyssey as the place where ships sheltered from storms.', 'teaser-card-s010-rollback:ab6ffb1d-c6d2-4c14-96e8-7f76a2607d7d:card_description', 'rollback of teaser-card-s010: card_description ''A Minoan port city from the 2nd millennium BC that served as the harbor for Knossos. Homer mentioned it in the Odyssey as the place where ships sheltered from storms.'' restored on Amnisos', '65a9eed6441db3b3894ab33990e58a8db24b548abfd4d2f1425b475f03e48640|621b88763a2a387075dedff23d1b7ca0586012afc34add0ef35bd59f46224a1e|621b88763a2a387075dedff23d1b7ca0586012afc34add0ef35bd59f46224a1e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the north coast of Crete, Amnisos was a Bronze Age port to the palace city of Knossos. The sea now stands three meters higher, and walls of submerged houses can be seen from the shore."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Amnisos lies on the north coast of Crete [S1]; Amnisos was a Bronze Age port [S1]; the port served the palace city of Knossos [S1]; the sea now stands three meters higher than in the Bronze Age [S4]; walls of submerged houses can be seen from the shore [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Amnisos is a settlement (a port) on the north coast of Crete, the central claim about what and where the site is [SUPPORTED: https://en.wikipedia.org/wiki/Amnisos]; Amnisos dates to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Amnisos]; Amnisos was a port to the palace city of Knossos [SUPPORTED: https://en.wikipedia.org/wiki/Amnisos]; The sea now stands three meters higher than in the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Amnisos]; The walls of submerged houses can be seen from the shore [SUPPORTED: https://en.wikipedia.org/wiki/Amnisos]"}]'::jsonb),
    ('ac3877a0-04fc-4049-b918-ebf41b0a1501'::uuid, 'card_description', 'The dry desert kept the Cerro Pátapo Ruins remarkably well preserved: a Wari city near Chiclayo with special spots set aside for human sacrifice and a pile of bones at the foot of a cliff.', 'Wari culture city from 350–1000 AD, remarkably preserved by desert air. Artefacts of the northern Wari tradition distinguish this coastal site from the Ayacucho heartland far to the south.', 'teaser-card-s010-rollback:ac3877a0-04fc-4049-b918-ebf41b0a1501:card_description', 'rollback of teaser-card-s010: card_description ''Wari culture city from 350–1000 AD, remarkably preserved by desert air. Artefacts of the northern Wari tradition distinguish this coastal site from the Ayacucho heartland far to the south.'' restored on Cerro Pátapo Ruins', '3b5e0154782c87e9965261b4a7e160a06fc93d56fcfe1c0e65f3ac38a7e26c4e|e90fbb682f59655e3bb1de7e8053272678e53b4c08ab70e43f6595355eb9bc98|e90fbb682f59655e3bb1de7e8053272678e53b4c08ab70e43f6595355eb9bc98', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The dry desert kept the Cerro Pátapo Ruins remarkably well preserved: a Wari city near Chiclayo with special spots set aside for human sacrifice and a pile of bones at the foot of a cliff."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the dry desert climate kept the ruins well preserved [S5]; the preservation is remarkable [S5]; the site is a Wari city [S1, S2, S4]; the site is near Chiclayo [S1]; the site has special spots set aside for human sacrifice [S6]; the site has a pile of bones at the foot of a cliff [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Cerro Pátapo Ruins are a city (the remains of a pre-Columbian city), the central claim about what kind of place the site is [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_P%C3%A1tapo_ruins]; The city lies near Chiclayo (in Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_P%C3%A1tapo_ruins]; The city is Wari (a Wari city) [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_P%C3%A1tapo_ruins]; The site is remarkably well preserved [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_P%C3%A1tapo_ruins]; The preservation is owed to the dry desert (climate) [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_P%C3%A1tapo_ruins]; The site has evidence of human sacrifice, with special spots set aside for it [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_P%C3%A1tapo_ruins]; The site has a pile of bones at the foot of a cliff [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_P%C3%A1tapo_ruins]"}]'::jsonb),
    ('ac46cdfd-877f-47d4-8403-90d21983364f'::uuid, 'card_description', 'Once called Cecropia after the legendary serpent-man Cecrops, the Acropolis of Athens rises on a rocky outcrop where Pericles coordinated the building of the Parthenon and the Erechtheion.', 'A temple to Athena Polias, the tutelary deity of the city, was erected between 570 and 550 BC.', 'teaser-card-s010-rollback:ac46cdfd-877f-47d4-8403-90d21983364f:card_description', 'rollback of teaser-card-s010: card_description ''A temple to Athena Polias, the tutelary deity of the city, was erected between 570 and 550 BC.'' restored on Acropolis of Athens', '3b7b096c5e5bdde4cafd4ddbce86b949aa441e6e6272595c44068a63f6e2f674|f0bb5d82b9fc6cd3f4a9c89eb08bfe08830952be49cfb7692be99914a1ba2e52|f0bb5d82b9fc6cd3f4a9c89eb08bfe08830952be49cfb7692be99914a1ba2e52', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Once called Cecropia after the legendary serpent-man Cecrops, the Acropolis of Athens rises on a rocky outcrop where Pericles coordinated the building of the Parthenon and the Erechtheion."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Acropolis of Athens was once called Cecropia [S2]; the name Cecropia comes from Cecrops [S2]; Cecrops is a legendary serpent-man [S2]; the Acropolis rises on a rocky outcrop [S1]; Pericles coordinated the building of the Parthenon [S3]; Pericles coordinated the building of the Erechtheion [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Acropolis of Athens is an ancient citadel, the central claim about what kind of place the site is [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]; The Acropolis of Athens rises on a rocky outcrop above Athens, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]; The Acropolis of Athens was once called Cecropia [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]; The name Cecropia derives from Cecrops (named after him) [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]; Cecrops was a legendary serpent-man [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]; Pericles coordinated the construction of the Acropolis buildings whose remains are the site''s most important ones [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]; The buildings Pericles coordinated include the Parthenon [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]; The buildings Pericles coordinated include the Erechtheion [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_of_Athens]"}]'::jsonb),
    ('aceee58f-9865-4095-8bff-bef66f5baa73'::uuid, 'card_description', 'Large polychrome figures are a striking feature of Mojeque in northern Peru, whose main mound is a stepped pyramid of at least six platforms, about 30 m in height and almost quadrangular.', 'A temple complex from 1800 BC with massive mound platforms and human-sized sculpted heads depicting deities. Large crowds gathered here for ceremonies long before the Inca existed.', 'teaser-card-s010-rollback:aceee58f-9865-4095-8bff-bef66f5baa73:card_description', 'rollback of teaser-card-s010: card_description ''A temple complex from 1800 BC with massive mound platforms and human-sized sculpted heads depicting deities. Large crowds gathered here for ceremonies long before the Inca existed.'' restored on Mojeque', 'ee615516eccac44aec778a82bed4381558ff80dcecc3f434a33c329eae7ab94f|d50711a1b61ec149d3f96d605fe4c7c3fc99481a8d7b02ac773ec047baeb1a24|d50711a1b61ec149d3f96d605fe4c7c3fc99481a8d7b02ac773ec047baeb1a24', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Large polychrome figures are a striking feature of Mojeque in northern Peru, whose main mound is a stepped pyramid of at least six platforms, about 30 m in height and almost quadrangular."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "large polychrome figures are a striking feature of Mojeque [S3]; Mojeque is in northern Peru [S1]; the main mound is a stepped pyramid [S6]; the pyramid has at least six platforms [S6]; the mound is about 30 m in height [S7]; the mound is almost quadrangular [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mojeque is a large archaeological site (a mound and pyramid complex), the central claim about what kind of place the site is [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]; Mojeque lies in northern Peru [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]; Mojeque has large polychrome figures [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]; The large polychrome figures are a striking feature of the site [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]; The main mound of Mojeque is a stepped pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]; The main mound has at least six platforms [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]; The main mound is about 30 m in height [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]; The main mound is almost quadrangular [SUPPORTED: https://en.wikipedia.org/wiki/Mojeque]"}]'::jsonb),
    ('addfeb62-4424-4c58-8a2a-0c5e26a98df9'::uuid, 'card_description', 'Mosaics with geometrical and naturalistic motifs adorn the main rooms of the Roman Ruins of Pisões, a farming villa that supplied Pax Julia with foodstuffs, watered from a nearby Roman dam.', 'A Roman villa dating from the 1st century AD with an olive-oil production facility. Rome''s insatiable demand for oil drove estates across the empire.', 'teaser-card-s010-rollback:addfeb62-4424-4c58-8a2a-0c5e26a98df9:card_description', 'rollback of teaser-card-s010: card_description "A Roman villa dating from the 1st century AD with an olive-oil production facility. Rome''s insatiable demand for oil drove estates across the empire." restored on Roman Ruins of Pisões', '66ffabecb5735d6c36d5a5fa4e872404ffc6f63c0322ecaf385633c9beaa2ac0|31faad989c1892ca0cbd6039ef0f1bb93e8b3710b459e3983493cb3259563f34|31faad989c1892ca0cbd6039ef0f1bb93e8b3710b459e3983493cb3259563f34', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mosaics with geometrical and naturalistic motifs adorn the main rooms of the Roman Ruins of Pisões, a farming villa that supplied Pax Julia with foodstuffs, watered from a nearby Roman dam."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "mosaics with geometrical and naturalistic motifs are found in the main rooms [S5]; the site is the Roman Ruins of Pisões [S1]; it is a farming villa [S1, S2]; it supplied Pax Julia with foodstuffs [S2]; a nearby Roman dam supplied water to the villa [S3, S7, S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Ruins of Pisões are a Roman villa rustica (a farming villa) in the Beja municipality of Portugal, the central claim about what and where the site is [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Pis%C3%B5es]; Mosaics with geometrical and naturalistic motifs decorate the main (more important) rooms of the villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Pis%C3%B5es]; The villa was a farm that supplied the city of Pax Julia with foodstuffs [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Pis%C3%B5es]; A Roman dam lies near the villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Pis%C3%B5es]; The villa was supplied with water from the nearby Roman dam [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Pis%C3%B5es]"}]'::jsonb),
    ('ae2ca7b1-89da-46cb-8924-f9d04dd5da2e'::uuid, 'card_description', 'At Banias a spring once associated with the god Pan rose from a large cave in a sheer cliff, gradually lined with shrines. It is the source of a main tributary of the Jordan River.', 'A city sacred to the Greek god Pan, inhabited for 2,000 years until 1967. A shrine to Pan was carved directly into the rock beside one of the Jordan River''s main sources.', 'teaser-card-s010-rollback:ae2ca7b1-89da-46cb-8924-f9d04dd5da2e:card_description', 'rollback of teaser-card-s010: card_description "A city sacred to the Greek god Pan, inhabited for 2,000 years until 1967. A shrine to Pan was carved directly into the rock beside one of the Jordan River''s main sources." restored on Banias', '1b0af2c236d62482aaee6ae6c8c79ea897a3e87d0506cda75cc2f35b04f7db5c|9feda479fc4f00edcc54e134837766b0a7109c2351a01774b11abf39c51ce23c|9feda479fc4f00edcc54e134837766b0a7109c2351a01774b11abf39c51ce23c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Banias a spring once associated with the god Pan rose from a large cave in a sheer cliff, gradually lined with shrines. It is the source of a main tributary of the Jordan River."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the place is Banias [S1]; a spring at Banias was once associated with the god Pan [S1]; the spring rose (originated) in a large cave [S3]; the cave is in a sheer cliff [S3]; the cave/cliff face was gradually lined with shrines [S3]; the spring is the source of a main tributary of the Jordan River [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Banias is a site (in the Golan Heights, Syria) at a natural spring [SUPPORTED: https://en.wikipedia.org/wiki/Banias]; The spring was once associated with the god Pan [SUPPORTED: https://en.wikipedia.org/wiki/Banias]; The spring rose from a large cave [SUPPORTED: https://en.wikipedia.org/wiki/Banias]; The cave was in a sheer cliff [SUPPORTED: https://en.wikipedia.org/wiki/Banias]; The cave was gradually lined with shrines [SUPPORTED: https://en.wikipedia.org/wiki/Banias]; The spring is the source of a river (the Banias River) [SUPPORTED: https://en.wikipedia.org/wiki/Banias]; That river is one of the main tributaries of the Jordan River [SUPPORTED: https://en.wikipedia.org/wiki/Banias]"}]'::jsonb),
    ('ae2d2c32-689c-443f-ba05-e70023619136'::uuid, 'card_description', 'At the heart of the Bronze Age palace of Knossos lies the Throne Room, a ceremonial chamber of the 15th century BC with gypsum benches on three sides, unearthed by Arthur Evans in 1900.', 'The oldest throne room in Europe, from the 15th century BC at the palace of Knossos. Griffin frescoes flank the gypsum throne, which still sits in place.', 'teaser-card-s010-rollback:ae2d2c32-689c-443f-ba05-e70023619136:card_description', 'rollback of teaser-card-s010: card_description ''The oldest throne room in Europe, from the 15th century BC at the palace of Knossos. Griffin frescoes flank the gypsum throne, which still sits in place.'' restored on Throne Room, Knossos', 'c5f2d7da21f23a45cf6b15ea1e0793ae81ac121e70fe1e277fe0440f285683d0|bb14e4fc0076714f8615534a032825d5f90acedbab5e7a083312bb93b6e94263|bb14e4fc0076714f8615534a032825d5f90acedbab5e7a083312bb93b6e94263', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At the heart of the Bronze Age palace of Knossos lies the Throne Room, a ceremonial chamber of the 15th century BC with gypsum benches on three sides, unearthed by Arthur Evans in 1900."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "it lies at the heart of the Bronze Age palace of Knossos [S2]; the site is the Throne Room [S1]; it is a ceremonial chamber [S1]; it dates to the 15th century BC [S1]; it has gypsum benches on three sides [S5]; it was unearthed by Arthur Evans [S3]; it was unearthed in 1900 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Throne Room is a ceremonial chamber [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; The Throne Room lies inside the palace of Knossos (Crete, Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; Knossos is a Bronze Age palace [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; The Throne Room lies at the heart of the palace [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; The chamber dates to the 15th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; The chamber has gypsum benches [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; The gypsum benches stand on three sides [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; The Throne Room was unearthed by Arthur Evans [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]; The Throne Room was unearthed in 1900 [SUPPORTED: https://en.wikipedia.org/wiki/Throne_Room,_Knossos]"}]'::jsonb),
    ('ae519f45-f80c-4464-8f76-e9d986803c34'::uuid, 'card_description', 'On Anglesey, two quartz-rich boulders about 4.1 and 3 metres high appear to stand in their original positions, a slab between them read as the former capstone of Henblas Burial Chamber.', 'Henblas Burial Chamber is a Neolithic dolmen located in Henblas, to the southwest of Llangristiolus, Anglesey.', 'teaser-card-s010-rollback:ae519f45-f80c-4464-8f76-e9d986803c34:card_description', 'rollback of teaser-card-s010: card_description ''Henblas Burial Chamber is a Neolithic dolmen located in Henblas, to the southwest of Llangristiolus, Anglesey.'' restored on Henblas Burial Chamber', '99c2681454b1688b0178ed7d0510f3ca14426b25f54a52e136dea3b193c79aa7|574d073bc26d1d1851b086d7be9381a45f8a13a6ad1be7243f434635ad1862cd|574d073bc26d1d1851b086d7be9381a45f8a13a6ad1be7243f434635ad1862cd', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Anglesey, two quartz-rich boulders about 4.1 and 3 metres high appear to stand in their original positions, a slab between them read as the former capstone of Henblas Burial Chamber."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is on Anglesey [S1]; two boulders stand there [S2]; the boulders are quartz-rich [S2]; the boulders are about 4.1 and 3 metres high [S2]; the boulders appear to stand in their original positions (hedged) [S3]; a slab lies between the boulders [S2]; the slab is read (interpreted) as the former capstone (hedged) [S2]; the site is Henblas Burial Chamber [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Henblas Burial Chamber is a burial chamber (a Neolithic dolmen) [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; Henblas Burial Chamber is on Anglesey [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; The structure consists of two boulders [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; The boulders are quartz-rich [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; One boulder is about 4.1 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; The other boulder is about 3 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; The boulders appear to stand in their original positions [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; A large slab lies between the boulders [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]; The slab between the boulders is interpreted as the former capstone [SUPPORTED: https://en.wikipedia.org/wiki/Henblas_Burial_Chamber]"}]'::jsonb),
    ('b0c061fd-8644-433e-a61c-9b20fd960c26'::uuid, 'card_description', 'On Lake Neuchâtel''s northern shore lies La Tène, the type site of the La Tène culture. Around 1870 the lake fell 2.7 m, and a site believed to be exhausted proved to have more to be found.', 'A lakeside deposit on Lake Neuchâtel dating from roughly 450 BC to the late Iron Age. Artifacts pulled from the water define Celtic material culture across a zone stretching from Ireland to Anatolia.', 'teaser-card-s010-rollback:b0c061fd-8644-433e-a61c-9b20fd960c26:card_description', 'rollback of teaser-card-s010: card_description ''A lakeside deposit on Lake Neuchâtel dating from roughly 450 BC to the late Iron Age. Artifacts pulled from the water define Celtic material culture across a zone stretching from Ireland to Anatolia.'' restored on La Tène - Archaeological Site', '377054064e8d4acf09a7f8eb349a635bb83f40488bf843a6282abf16d6bebc39|0d68427dce9f42bd1283701c8b6823b8a9e07e90324d5f09b006c6887a23b5c2|0d68427dce9f42bd1283701c8b6823b8a9e07e90324d5f09b006c6887a23b5c2', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Lake Neuchâtel''s northern shore lies La Tène, the type site of the La Tène culture. Around 1870 the lake fell 2.7 m, and a site believed to be exhausted proved to have more to be found."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "La Tène lies on the northern shore of Lake Neuchâtel [S1]; La Tène is the type site of the La Tène culture [S2]; around 1870 the lake level fell 2.7 m [S8]; the site was believed to be exhausted [S8]; the site proved to have more to be found [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "La Tène is an archaeological site in Switzerland [SUPPORTED: https://en.wikipedia.org/wiki/La_T%C3%A8ne_(archaeological_site)]; La Tène lies on the northern shore of Lake Neuchâtel [SUPPORTED: https://en.wikipedia.org/wiki/La_T%C3%A8ne_(archaeological_site)]; La Tène is the type site of the La Tène culture [SUPPORTED: https://en.wikipedia.org/wiki/La_T%C3%A8ne_(archaeological_site)]; Around 1870 the lake level was lowered (the first Jura water correction) [SUPPORTED: https://en.wikipedia.org/wiki/La_T%C3%A8ne_(archaeological_site)]; The lake level fell by 2.7 m [SUPPORTED: https://en.wikipedia.org/wiki/La_T%C3%A8ne_(archaeological_site)]; The site, believed to be exhausted, proved to have more to be found [SUPPORTED: https://en.wikipedia.org/wiki/La_T%C3%A8ne_(archaeological_site)]"}]'::jsonb),
    ('b1e7b190-e66c-49da-8df8-2b1345fa68fd'::uuid, 'card_description', 'Near Lake Titicaca, Tiwanaku once spanned roughly 4 square kilometers. Digging into its terraced platform mound, the Akapana, revealed sacrificial dedications of humans and camelids.', 'Tiwanaku began its steady growth in the early centuries of the first millennium AD. Excavations of the Akapana at Tiwanaku revealed the remains of sacrificial dedications of humans and camelids.', 'teaser-card-s010-rollback:b1e7b190-e66c-49da-8df8-2b1345fa68fd:card_description', 'rollback of teaser-card-s010: card_description ''Tiwanaku began its steady growth in the early centuries of the first millennium AD. Excavations of the Akapana at Tiwanaku revealed the remains of sacrificial dedications of humans and camelids.'' restored on Tiwanaku', '46d5c55415320e1925ee1c44527bc81cb65236da313460cc1cfed7a8fbf1be04|d3c467c6c10909161b8d14edc0006a030db90f53f4a8428d4add78f4e21c3e14|d3c467c6c10909161b8d14edc0006a030db90f53f4a8428d4add78f4e21c3e14', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near Lake Titicaca, Tiwanaku once spanned roughly 4 square kilometers. Digging into its terraced platform mound, the Akapana, revealed sacrificial dedications of humans and camelids."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tiwanaku is near Lake Titicaca [S1]; at its height it once spanned roughly 4 square kilometers [S3]; the Akapana is a terraced platform mound at Tiwanaku [S4]; excavation of the Akapana revealed sacrificial dedications [S6]; the dedications were of humans and camelids [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tiwanaku is a Pre-Columbian archaeological site in Bolivia [SUPPORTED: https://en.wikipedia.org/wiki/Tiwanaku]; Tiwanaku lies near Lake Titicaca [SUPPORTED: https://en.wikipedia.org/wiki/Tiwanaku]; Tiwanaku once spanned roughly 4 square kilometers [SUPPORTED: https://en.wikipedia.org/wiki/Tiwanaku]; The Akapana is a terraced platform mound at Tiwanaku [SUPPORTED: https://en.wikipedia.org/wiki/Tiwanaku]; Excavation of the Akapana revealed sacrificial dedications [SUPPORTED: https://en.wikipedia.org/wiki/Tiwanaku]; The sacrificial dedications were of humans and camelids [SUPPORTED: https://en.wikipedia.org/wiki/Tiwanaku]"}]'::jsonb),
    ('b2a9c061-0761-4f66-9406-130bf68f6770'::uuid, 'card_description', 'Two concentric ramparts up to 5.8 metres high ring Warbstow Bury, an Iron Age hillfort in Cornwall. At its centre lies a medieval rabbit warren known as the Giant''s Grave.', 'Warbstow Bury is an Iron Age hillfort about 0.5 miles west of the village of Warbstow, in Cornwall.', 'teaser-card-s010-rollback:b2a9c061-0761-4f66-9406-130bf68f6770:card_description', 'rollback of teaser-card-s010: card_description ''Warbstow Bury is an Iron Age hillfort about 0.5 miles west of the village of Warbstow, in Cornwall.'' restored on Warbstow Bury', '880fc2ea6465ed3d2b099d2b292bb6c4f6b9ff5b7d96c539fe8f5dae733e1205|b2128db18c4c7c42c795399f7c0be2097c6838cd88971152dbf42241bf5de9d2|b2128db18c4c7c42c795399f7c0be2097c6838cd88971152dbf42241bf5de9d2', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Two concentric ramparts up to 5.8 metres high ring Warbstow Bury, an Iron Age hillfort in Cornwall. At its centre lies a medieval rabbit warren known as the Giant''s Grave."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "there are two concentric ramparts [S5]; the ramparts are up to 5.8 metres high [S5]; the ramparts ring (encircle) Warbstow Bury [S4, S5]; Warbstow Bury is an Iron Age hillfort [S1]; it is in Cornwall [S1]; at its centre lies a rabbit warren [S7]; the warren is medieval [S7]; the warren is known as the Giant''s Grave [S7, S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Warbstow Bury is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; Warbstow Bury is an Iron Age site [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; Warbstow Bury is in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; Warbstow Bury has two concentric ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; The ramparts ring the fort as an oval enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; The ramparts are up to 5.8 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; A rabbit warren lies at the centre of the fort [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; The warren is medieval [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]; The warren mound is known as the Giant''s Grave [SUPPORTED: https://en.wikipedia.org/wiki/Warbstow_Bury]"}]'::jsonb),
    ('b2b1beee-00c6-4dfa-a616-89f7be1b86b7'::uuid, 'card_description', 'Investigating looting in 1990, an archaeologist at Balamkú found a trench that had partly bared a painted Maya stucco frieze, 16.8 metres long, joining rulers with a sacred mountain.', 'A 300–600 AD stucco frieze depicts earth monsters, jaguars, and kings emerging from the underworld across a single facade. The site covers 25 hectares around this one monumental core.', 'teaser-card-s010-rollback:b2b1beee-00c6-4dfa-a616-89f7be1b86b7:card_description', 'rollback of teaser-card-s010: card_description ''A 300–600 AD stucco frieze depicts earth monsters, jaguars, and kings emerging from the underworld across a single facade. The site covers 25 hectares around this one monumental core.'' restored on Balamkú', '63edb6f3949691a9bf83a7a98a991351370a9832eaafc68a1148810fa7b87ea7|b57a28dbe965fca81842a56a58accca4343ca0fd296c25ecce8a9037024aa995|b57a28dbe965fca81842a56a58accca4343ca0fd296c25ecce8a9037024aa995', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Investigating looting in 1990, an archaeologist at Balamkú found a trench that had partly bared a painted Maya stucco frieze, 16.8 metres long, joining rulers with a sacred mountain."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the discovery was in 1990 [S5]; it was made while investigating (a report of) looting [S5]; an archaeologist made the find [S5]; the site is Balamkú [S1]; a trench (a looters'' trench) had partly uncovered a frieze [S5]; the frieze is painted [S5]; the frieze is stucco [S5]; the frieze is Maya [S1, S3]; the frieze is 16.8 metres long [S7]; the frieze joins (combines) imagery of rulers with a sacred mountain [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-