    ('d2b71745-bf32-4027-8920-18fcd5600c8d'::uuid, 'card_description', 'Southeast of Cusco, three Inca canals divert the Pukara river across Tipón, one flowing on top of an intact stone aqueduct, on a site continuously occupied from around 1000 BCE.', 'An Inca park with monumental terraces irrigated by canals fed by a natural spring. The hydraulic precision here rivals modern irrigation systems.', 'teaser-card-s010-rollback:d2b71745-bf32-4027-8920-18fcd5600c8d:card_description', 'rollback of teaser-card-s010: card_description ''An Inca park with monumental terraces irrigated by canals fed by a natural spring. The hydraulic precision here rivals modern irrigation systems.'' restored on Tipón', '0ca46b840cb2c5c2e2914fd8a3188fea1f628f18d0a0aca5b8378116044a7e50|0cbc9cf1c85f8832a8f7df50aaa64a0567b39d401ab395ae3fa251559b10c52b|0cbc9cf1c85f8832a8f7df50aaa64a0567b39d401ab395ae3fa251559b10c52b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Southeast of Cusco, three Inca canals divert the Pukara river across Tipón, one flowing on top of an intact stone aqueduct, on a site continuously occupied from around 1000 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies southeast of Cusco [S1]; three Inca canals cross the complex [S2]; the canals divert the waters of the Pukara river [S2]; one canal flows on top of an intact stone aqueduct [S2]; the site was continuously occupied [S4]; the continuous occupation began around 1000 BCE [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tipon is an Inca archaeological site (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]; Tipon lies southeast of Cusco [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]; There are three Inca canals at Tipon [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]; The three canals divert the waters of the Pukara river across the site [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]; One of the canals flows on top of a stone aqueduct [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]; The aqueduct is intact [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]; The site was continuously occupied [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]; The continuous occupation began around 1000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Tip%C3%B3n]"}]'::jsonb),
    ('d2b862c0-44e2-422f-9c17-5548b3c74a7f'::uuid, 'card_description', 'Rediscovered in November 1947 as a housing estate went up, Kings Weston Roman Villa retains its original mosaic floors, a hypocaust and the only Roman bath suite visible in Bristol.', 'A Roman villa discovered during 1947 housing construction. Visitors can see the only exposed Roman mosaic pavement in the entire city.', 'teaser-card-s010-rollback:d2b862c0-44e2-422f-9c17-5548b3c74a7f:card_description', 'rollback of teaser-card-s010: card_description ''A Roman villa discovered during 1947 housing construction. Visitors can see the only exposed Roman mosaic pavement in the entire city.'' restored on Kings Weston Roman Villa', '272a27d6ebb03671f88fd099401a447d2bea254c85fcda48ce5183321a2199b3|77fe88bd452953f95fd7c3c51cb3ba6a55821645fca445c2b6348536270a5847|77fe88bd452953f95fd7c3c51cb3ba6a55821645fca445c2b6348536270a5847', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Rediscovered in November 1947 as a housing estate went up, Kings Weston Roman Villa retains its original mosaic floors, a hypocaust and the only Roman bath suite visible in Bristol."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the villa was rediscovered in November 1947 [S5]; it was found as a housing estate was being built [S5]; it retains its original mosaic floors [S3]; it retains a hypocaust [S3]; it has the only Roman bath suite visible in Bristol [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Kings Weston Roman Villa is a Roman villa in (the north-west of) Bristol, England (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Kings_Weston_Roman_Villa]; The villa was rediscovered in November 1947 while a housing estate was being built [SUPPORTED: https://en.wikipedia.org/wiki/Kings_Weston_Roman_Villa]; The villa retains its original mosaic floors [SUPPORTED: https://en.wikipedia.org/wiki/Kings_Weston_Roman_Villa]; The villa retains a hypocaust [SUPPORTED: https://en.wikipedia.org/wiki/Kings_Weston_Roman_Villa]; It has the only Roman bath suite visible in Bristol (superlative) [SUPPORTED: https://en.wikipedia.org/wiki/Kings_Weston_Roman_Villa]"}]'::jsonb),
    ('d5a5f6ff-a9cd-424e-9af9-572b0844f980'::uuid, 'card_description', 'Timpone della Motta, a hill in Calabria inhabited since the Middle Bronze Age, became the acropolis and sanctuary of Greek colonists from Sybaris. Thousands of hydriskai were found there.', NULL, 'teaser-card-s010-rollback:d5a5f6ff-a9cd-424e-9af9-572b0844f980:card_description', 'rollback of teaser-card-s010: card_description None restored on Timpone della Motta', 'beefdd0557e7e5ff13d70a5832422c26b9f74fd650ad0c6cd9ef89923f334bcd|b2ca43d15803faea0b4d46d87dd2059ce077378fd2afe7df02e9f070f61c12ae|b2ca43d15803faea0b4d46d87dd2059ce077378fd2afe7df02e9f070f61c12ae', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Timpone della Motta, a hill in Calabria inhabited since the Middle Bronze Age, became the acropolis and sanctuary of Greek colonists from Sybaris. Thousands of hydriskai were found there."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Timpone della Motta is a hill [S1]; it is in Calabria [S1]; it has been inhabited since the Middle Bronze Age [S1]; Greek colonists from Sybaris turned it into their acropolis and sanctuary [S3]; thousands of hydriskai were found there [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Timpone della Motta is a hill in Calabria, Italy (the central claim: a hill site, acropolis and sanctuary) [SUPPORTED: https://en.wikipedia.org/wiki/Timpone_della_Motta]; The hill was inhabited since the Middle Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Timpone_della_Motta]; It became the acropolis of Greek colonists from Sybaris [SUPPORTED: https://en.wikipedia.org/wiki/Timpone_della_Motta]; It became a sanctuary of Greek colonists from Sybaris [SUPPORTED: https://en.wikipedia.org/wiki/Timpone_della_Motta]; Thousands of hydriskai were found there [SUPPORTED: https://en.wikipedia.org/wiki/Timpone_della_Motta]"}]'::jsonb),
    ('d6a95fc5-ad9c-4181-b04b-e57b8b0088da'::uuid, 'card_description', 'The Archaeological Park of Dion at Mount Olympus holds sanctuaries, bathhouses, shops and workshops. Here Alexander the Great sacrificed to Zeus before his campaign against the Persians.', 'A sacred city at the foot of Mount Olympus where Macedonian kings worshipped Zeus. Alexander the Great sacrificed here before marching against the Persian Empire.', 'teaser-card-s010-rollback:d6a95fc5-ad9c-4181-b04b-e57b8b0088da:card_description', 'rollback of teaser-card-s010: card_description ''A sacred city at the foot of Mount Olympus where Macedonian kings worshipped Zeus. Alexander the Great sacrificed here before marching against the Persian Empire.'' restored on Archaeological Park of Dion', 'aa5a1b2fd567f68fc9dd043f541f3a9e82b4427ab04b59fec143fa33bebdcf08|7d94b3bbd624cdf606872a07daf04868b138895094e369e3fa7e6259471d088a|7d94b3bbd624cdf606872a07daf04868b138895094e369e3fa7e6259471d088a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Archaeological Park of Dion at Mount Olympus holds sanctuaries, bathhouses, shops and workshops. Here Alexander the Great sacrificed to Zeus before his campaign against the Persians."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the park is at Mount Olympus [S1]; it holds sanctuaries [S2]; it holds bathhouses [S4]; it holds shops [S4]; it holds workshops [S4]; Alexander the Great sacrificed to Zeus in Dion [S6]; he did so before his campaign against the Persians [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Archaeological Park of Dion is an archaeological site (park) in Greece (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]; The park is at Mount Olympus [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]; The park holds sanctuaries [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]; The park holds bathhouses [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]; The park holds shops [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]; The park holds workshops [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]; Alexander the Great sacrificed to Zeus at Dion [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]; The sacrifice was before his campaign against the Persians [SUPPORTED: https://en.wikipedia.org/wiki/Archaeological_Park_of_Dion]"}]'::jsonb),
    ('d6bc5056-b3e5-4038-86f4-cdb08090202a'::uuid, 'card_description', 'On a hilltop in Warren Wood, approximately 90 metres above sea level, Wasteberry Camp looks out over Silverbridge Lake: an Iron Age hill fort near the hamlet of Blackpool, Devon.', 'Iron Age hillfort at ~90 m above Silverbridge Lake, 1st millennium BC. Southeast of Plympton near Blackpool hamlet, Wasteberry Camp commanded the high ground with few earthworks surviving today.', 'teaser-card-s010-rollback:d6bc5056-b3e5-4038-86f4-cdb08090202a:card_description', 'rollback of teaser-card-s010: card_description ''Iron Age hillfort at ~90 m above Silverbridge Lake, 1st millennium BC. Southeast of Plympton near Blackpool hamlet, Wasteberry Camp commanded the high ground with few earthworks surviving today.'' restored on Wasteberry Camp', '11ab009411bc44a1746b4e872631b85429c2d0db22c6517732e519cfebeac6a2|e10be6e369e6ddf3d8a2e769014c17917cfdc825b4ef06d5e17738c199e6c617|e10be6e369e6ddf3d8a2e769014c17917cfdc825b4ef06d5e17738c199e6c617', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a hilltop in Warren Wood, approximately 90 metres above sea level, Wasteberry Camp looks out over Silverbridge Lake: an Iron Age hill fort near the hamlet of Blackpool, Devon."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies on a hilltop in Warren Wood [S2]; the hilltop is approximately 90 metres above sea level [S2]; the site looks out over Silverbridge Lake [S2]; Wasteberry Camp is an Iron Age hill fort [S1]; it is near the hamlet of Blackpool [S1]; it is in Devon [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Wasteberry Camp is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Wasteberry_Camp]; The hill fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Wasteberry_Camp]; It is near the hamlet of Blackpool [SUPPORTED: https://en.wikipedia.org/wiki/Wasteberry_Camp]; It is in Devon (England) [SUPPORTED: https://en.wikipedia.org/wiki/Wasteberry_Camp]; The fort stands on a hilltop in Warren Wood [SUPPORTED: https://en.wikipedia.org/wiki/Wasteberry_Camp]; It lies approximately 90 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Wasteberry_Camp]; It looks out over Silverbridge Lake [SUPPORTED: https://en.wikipedia.org/wiki/Wasteberry_Camp]"}]'::jsonb),
    ('d78800a3-e78d-4c72-90b0-069140ad9b02'::uuid, 'card_description', 'On the plain of Amari lies Monastiraki, a Minoan town never built on after its destruction, where storehouses, sanctuaries and two archive rooms of earthenware stamps have come to light.', 'A Minoan town destroyed at the same time as the Old Palaces around 1700 BC. Its destruction layer preserves a snapshot of daily life at the exact moment catastrophe struck.', 'teaser-card-s010-rollback:d78800a3-e78d-4c72-90b0-069140ad9b02:card_description', 'rollback of teaser-card-s010: card_description ''A Minoan town destroyed at the same time as the Old Palaces around 1700 BC. Its destruction layer preserves a snapshot of daily life at the exact moment catastrophe struck.'' restored on Monastiraki, Crete', '023c7a8c5e9324ca0ba6a4314d68d30b6128eaf583ca67ba357e66074e744ee0|5cd83bbd97fd3bba2d74d870e33fdb89f30228ec1a9df42a4e905911ce1a2e10|5cd83bbd97fd3bba2d74d870e33fdb89f30228ec1a9df42a4e905911ce1a2e10', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the plain of Amari lies Monastiraki, a Minoan town never built on after its destruction, where storehouses, sanctuaries and two archive rooms of earthenware stamps have come to light."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies on the plain of Amari [S2]; Monastiraki is a Minoan town [S1]; the town was destroyed [S3]; the site was never built on after its destruction [S4]; storehouses have come to light [S5]; sanctuaries have come to light [S5]; two archive rooms of earthenware stamps have come to light [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Monastiraki is an ancient Minoan town (archaeological site) on Crete [SUPPORTED: https://en.wikipedia.org/wiki/Monastiraki,_Crete]; The site lies on the plain of Amari [SUPPORTED: https://en.wikipedia.org/wiki/Monastiraki,_Crete]; The town was destroyed (at the end of the Old Palace period) [SUPPORTED: https://en.wikipedia.org/wiki/Monastiraki,_Crete]; The town was never built on after its destruction [SUPPORTED: https://en.wikipedia.org/wiki/Monastiraki,_Crete]; Storehouses have come to light at the site [SUPPORTED: https://en.wikipedia.org/wiki/Monastiraki,_Crete]; Sanctuaries have come to light at the site [SUPPORTED: https://en.wikipedia.org/wiki/Monastiraki,_Crete]; Two archive rooms of earthenware stamps have come to light at the site [SUPPORTED: https://en.wikipedia.org/wiki/Monastiraki,_Crete]"}]'::jsonb),
    ('d7c375d0-6ddc-42ed-a3d4-f128c3c1d89f'::uuid, 'card_description', 'In 1954, while Sylt Airport was under development, the stones of the Harhoog were moved to the coast near Keitum: a Funnelbeaker dolmen whose graves probably date to around 3000 BC.', 'Dating to 3000 BC, this Funnelbeaker dolmen near Keitum was moved stone by stone in 1954 when an airport displaced it. Of roughly 600 such graves once on this island, half survive.', 'teaser-card-s010-rollback:d7c375d0-6ddc-42ed-a3d4-f128c3c1d89f:card_description', 'rollback of teaser-card-s010: card_description ''Dating to 3000 BC, this Funnelbeaker dolmen near Keitum was moved stone by stone in 1954 when an airport displaced it. Of roughly 600 such graves once on this island, half survive.'' restored on Harhoog', 'e96d39b6d730a38f9f30e8f32824b4933f5caf39a926a9e011888612a13ee3dd|2f8129a8d9496499593e5114e18c9321b15ab9e00109c2620797400df1b83d07|2f8129a8d9496499593e5114e18c9321b15ab9e00109c2620797400df1b83d07', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In 1954, while Sylt Airport was under development, the stones of the Harhoog were moved to the coast near Keitum: a Funnelbeaker dolmen whose graves probably date to around 3000 BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the stones of the Harhoog were moved in 1954 [S3]; the move happened while Sylt Airport was under development [S3]; the stones were moved to the coast near Keitum [S3]; the Harhoog is a Funnelbeaker dolmen [S1, S5]; its graves probably date to around 3000 BC [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Harhoog is a dolmen (megalithic tomb) near Keitum on Sylt [SUPPORTED: https://en.wikipedia.org/wiki/Harhoog]; It is a Funnelbeaker (culture) dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Harhoog]; The stones of the Harhoog were moved in 1954 [SUPPORTED: https://en.wikipedia.org/wiki/Harhoog]; The stones were moved to the coast near Keitum [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Harhoog]; The move happened while Sylt Airport was under development [SUPPORTED: https://en.wikipedia.org/wiki/Harhoog]; The graves probably date to around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Harhoog]"}]'::jsonb),
    ('d82e4a95-00dd-4c1d-8e94-dd201f72e331'::uuid, 'card_description', 'On a cliff in the Gersac valley, La Chaire a Calvin bears a sculpted Magdalenian frieze: an aurochs without its head, a pregnant tarpan and mating tarpans, approximately 15000 years BP.', 'A rock shelter with a carved animal frieze from 13,000 BC depicting rhinoceros, deer, and aurochs. Among the oldest sculptured friezes in western Europe.', 'teaser-card-s010-rollback:d82e4a95-00dd-4c1d-8e94-dd201f72e331:card_description', 'rollback of teaser-card-s010: card_description ''A rock shelter with a carved animal frieze from 13,000 BC depicting rhinoceros, deer, and aurochs. Among the oldest sculptured friezes in western Europe.'' restored on La Chaire a Calvin', '33cb8a38d8092790c47be195b13847a0226e3efe2807ef64faa7cf82200d6f6f|ace21d51eb960af35bce90ec4bebe026296c4284d00990314d546d13484595d6|ace21d51eb960af35bce90ec4bebe026296c4284d00990314d546d13484595d6', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a cliff in the Gersac valley, La Chaire a Calvin bears a sculpted Magdalenian frieze: an aurochs without its head, a pregnant tarpan and mating tarpans, approximately 15000 years BP."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is on a cliff [S2]; the site is in the Gersac valley [S1]; the rock face bears a sculpted frieze [S3]; the frieze is Magdalenian [S3]; the frieze shows an aurochs without its head [S7]; the frieze shows a pregnant tarpan [S7]; the frieze shows mating tarpans [S7]; the frieze dates to approximately 15000 years BP [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "La Chaire a Calvin is a rock shelter with a sculpted frieze on its rock face (the site is a rock shelter bearing a sculpted frieze) [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]; The site lies in the valley of the Gersac (stream) [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]; The shelter is on a cliff [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]; The frieze is sculpted and Magdalenian in date [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]; The frieze shows an aurochs without its head [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]; The frieze shows a pregnant tarpan [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]; The frieze shows mating tarpans [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]; The frieze dates to approximately 15000 years BP [SUPPORTED: https://en.wikipedia.org/wiki/La_Chaire_a_Calvin]"}]'::jsonb),
    ('d8af7833-8171-40a3-a24c-cd3fff898c07'::uuid, 'card_description', 'At Karnak, the Temple of Ptah has six small gateways built close together; the sixth runs directly into the central sanctuary, where the statue of Ptah stands. Baboon figurines were found.', 'Built by Thutmose III on a Middle Kingdom foundation and enlarged by the Ptolemies, this Karnak shrine honours Ptah, Sekhmet, and Nefertum. Its history spans roughly 1800 BC to the 1st century AD.', 'teaser-card-s010-rollback:d8af7833-8171-40a3-a24c-cd3fff898c07:card_description', 'rollback of teaser-card-s010: card_description ''Built by Thutmose III on a Middle Kingdom foundation and enlarged by the Ptolemies, this Karnak shrine honours Ptah, Sekhmet, and Nefertum. Its history spans roughly 1800 BC to the 1st century AD.'' restored on Temple of Ptah, Sekhmet and Nefertom', 'fa68aec0f5addd1af1fb88d32228af5a6c31035c434a2619a4d83d7d9edd2ef2|07889e7fdd1f455efc71f21dd8a6d56a088823ced6b83aa11fe86c69e2a41c7c|07889e7fdd1f455efc71f21dd8a6d56a088823ced6b83aa11fe86c69e2a41c7c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Karnak, the Temple of Ptah has six small gateways built close together; the sixth runs directly into the central sanctuary, where the statue of Ptah stands. Baboon figurines were found."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Temple of Ptah is at Karnak [S1]; the temple has six gateways [S3]; the gateways are small [S3]; the gateways are built close together [S3]; the sixth gateway runs directly into the central sanctuary [S4]; the statue of Ptah stands in the central sanctuary [S4]; baboon figurines were found at the temple [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Temple of Ptah is a temple (shrine) at Karnak [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]; The temple is located at Karnak (within the Precinct of Amun-Re, Luxor) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]; The temple has six small gateways [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]; The gateways are small [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]; The six gateways are built close together [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]; The sixth gateway runs directly into the central sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]; The statue of Ptah stands in the central sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]; Baboon figurines were found at the temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ptah_(Karnak)]"}]'::jsonb),
    ('d8c32771-f319-4432-9333-aa646e273001'::uuid, 'card_description', 'On a hill 450 m above sea level, the Illyrian town of Dimale was walled around the mid-4th century BC and later gained stoas, a temple and a theater. Tiles stamped DIMALLITAN identified it.', '4th-century BC Illyrian hilltop city 450 m above the Adriatic, in the territory of the Parthini tribe. Dimale peaked in the Hellenistic period before passing to Macedonian, then Roman control.', 'teaser-card-s010-rollback:d8c32771-f319-4432-9333-aa646e273001:card_description', 'rollback of teaser-card-s010: card_description ''4th-century BC Illyrian hilltop city 450 m above the Adriatic, in the territory of the Parthini tribe. Dimale peaked in the Hellenistic period before passing to Macedonian, then Roman control.'' restored on Dimale', '8813101fd8b1a981f89d8ecfb8ef384a75b05b5ff01e73f94163d3c369942422|0bce3d025ae99ac492822ada4a6a260929e61360f80c52fe9b1f5174b4a29a35|0bce3d025ae99ac492822ada4a6a260929e61360f80c52fe9b1f5174b4a29a35', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a hill 450 m above sea level, the Illyrian town of Dimale was walled around the mid-4th century BC and later gained stoas, a temple and a theater. Tiles stamped DIMALLITAN identified it."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the town stands on a hill 450 m above sea level [S2]; Dimale is an Illyrian town [S1, S3, S5]; the town was walled around the mid-4th century BC [S3]; the town later gained several stoas [S4]; the town later gained a temple [S4]; the town later gained a theater [S4]; tiles stamped DIMALLITAN identified the site as Dimale [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dimale was an Illyrian town (a walled hilltop town of the Illyrian Parthini) [SUPPORTED: https://en.wikipedia.org/wiki/Dimale]; Dimale lies in Albania (Krotine, Berat County) [SUPPORTED: https://en.wikipedia.org/wiki/Dimale]; The town stood on a hill 450 m above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Dimale]; The first walls of Dimale were built around the mid-4th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Dimale]; The town later gained stoas, a temple and a theater [SUPPORTED: https://en.wikipedia.org/wiki/Dimale]; Tiles stamped DIMALLITAN identified the site as Dimale [SUPPORTED: https://en.wikipedia.org/wiki/Dimale]; The stoas, temple and theater came in the 3rd and 2nd centuries BC, later than the first walls [SUPPORTED: https://en.wikipedia.org/wiki/Dimale]"}]'::jsonb),
    ('d8d9d536-918c-461f-a05f-4080c8660afa'::uuid, 'card_description', 'Around 4,000 years ago Neolithic settlers came to the Niumatou Site, the oldest in central Taiwan. They left pottery and so many stone hoes that they probably relied largely on farming.', 'The oldest archaeological site in the central part of the island, with habitation from around 4,000 years ago. Neolithic people here knew agriculture and lived in settled communities.', 'teaser-card-s010-rollback:d8d9d536-918c-461f-a05f-4080c8660afa:card_description', 'rollback of teaser-card-s010: card_description ''The oldest archaeological site in the central part of the island, with habitation from around 4,000 years ago. Neolithic people here knew agriculture and lived in settled communities.'' restored on Niumatou Site', 'f030396e410ca6c29f9a93c8e49fb43737d68c6fdfdc686e220f6503e68ed680|d87ba1d62aa1a0b78a74cb09814f74c81c2e7380e9afe059e9a39b775398ad52|d87ba1d62aa1a0b78a74cb09814f74c81c2e7380e9afe059e9a39b775398ad52', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Around 4,000 years ago Neolithic settlers came to the Niumatou Site, the oldest in central Taiwan. They left pottery and so many stone hoes that they probably relied largely on farming."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "around 4,000 years ago Neolithic settlers came to the site [S3]; the Niumatou Site is the oldest (archaeological site) in central Taiwan [S2]; the settlers left pottery [S4]; large numbers of stone hoes were left/unearthed [S5]; the settlers probably relied largely on farming [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Niumatou Site is a Neolithic archaeological site in Qingshui District, Taichung, in central Taiwan [SUPPORTED: https://en.wikipedia.org/wiki/Niumatou_Site]; Neolithic settlers came to the site around 4,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Niumatou_Site]; The Niumatou Site is the oldest site in central Taiwan [SUPPORTED: https://en.wikipedia.org/wiki/Niumatou_Site]; The settlers left pottery [SUPPORTED: https://en.wikipedia.org/wiki/Niumatou_Site]; Large numbers of stone hoes were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Niumatou_Site]; Because of the many stone hoes, the settlers probably relied largely on farming [SUPPORTED: https://en.wikipedia.org/wiki/Niumatou_Site]"}]'::jsonb),
    ('d9023096-4bef-47a7-bcb4-2e3f4cf0ba36'::uuid, 'card_description', 'Near a Roman aqueduct in Amadora lies the Roman Villa of Quinta da Bolacha, built during the Roman occupation of the Iberian peninsula and occupied in the 3rd and 4th century.', '3rd–4th century Roman villa in Amadora linked to a nearby aqueduct. Excavations found a mortar tank and Chalcedony mining evidence — luxury stone extraction alongside ordinary estate life.', 'teaser-card-s010-rollback:d9023096-4bef-47a7-bcb4-2e3f4cf0ba36:card_description', 'rollback of teaser-card-s010: card_description ''3rd–4th century Roman villa in Amadora linked to a nearby aqueduct. Excavations found a mortar tank and Chalcedony mining evidence — luxury stone extraction alongside ordinary estate life.'' restored on Roman Villa of Quinta da Bolacha', 'eed96a6f0038228175e54007050a98f035dd2aa1f7bca8ea07e9fcde9db12ad5|dcaecfa32bf05f839961684c46529afe8b088148899afc1d46ec4b44f3282809|dcaecfa32bf05f839961684c46529afe8b088148899afc1d46ec4b44f3282809', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near a Roman aqueduct in Amadora lies the Roman Villa of Quinta da Bolacha, built during the Roman occupation of the Iberian peninsula and occupied in the 3rd and 4th century."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the villa is near a Roman aqueduct [S2]; the villa is in Amadora [S1]; it is a Roman villa [S1]; it was built during the Roman occupation of the Iberian peninsula [S3]; it was occupied in the 3rd and 4th century [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Villa of Quinta da Bolacha is a Roman villa in Amadora, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Quinta_da_Bolacha]; The villa lies near a Roman aqueduct [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Quinta_da_Bolacha]; The villa was built during the Roman occupation of the Iberian peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Quinta_da_Bolacha]; The villa was occupied in the 3rd and 4th century [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Quinta_da_Bolacha]; A Roman aqueduct is known in the municipality of Amadora [SUPPORTED: https://www.cm-amadora.pt/pt/cultura/museu-municipal-de-arqueologia/675-villa-romana-da-quinta-da-bolacha.html]"}]'::jsonb),
    ('d972a5b7-866c-48d6-af54-d9ac91f00b0b'::uuid, 'card_description', 'On Rapa Nui, three principal ahu run north to south at the Tahai Ceremonial Complex, Ko Te Riku with its restored eyes. Archaeologist William Mulloy and his wife are buried here.', 'Three moai platforms, one topped by a statue with restored white coral eyes. It shows how moai originally looked—wide-eyed and watching.', 'teaser-card-s010-rollback:d972a5b7-866c-48d6-af54-d9ac91f00b0b:card_description', 'rollback of teaser-card-s010: card_description ''Three moai platforms, one topped by a statue with restored white coral eyes. It shows how moai originally looked—wide-eyed and watching.'' restored on Tahai Ceremonial Complex', '028d7db402bfccd6e6dca349a5724f44eda96dfcc0d6fca8dd8caa6aed7f7cdd|c520d09140ff4dc3e1fd0dc601089ce3f5811eedc725295267ef821639c0a2cd|c520d09140ff4dc3e1fd0dc601089ce3f5811eedc725295267ef821639c0a2cd', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Rapa Nui, three principal ahu run north to south at the Tahai Ceremonial Complex, Ko Te Riku with its restored eyes. Archaeologist William Mulloy and his wife are buried here."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tahai Ceremonial Complex is on Rapa Nui [S1]; the complex has three principal ahu [S2]; the three principal ahu run from north to south [S2]; one of them is Ko Te Riku [S2]; Ko Te Riku has restored eyes [S2]; William Mulloy was an archaeologist [S2]; Mulloy and his wife are buried at Tahai [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Tahai Ceremonial Complex is an archaeological site (a ceremonial complex) on Rapa Nui [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; The site lies in Chile (Rapa Nui is part of Chilean Polynesia) [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; Tahai has three principal ahu [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; The three principal ahu run north to south [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; Ko Te Riku is one of the principal ahu at Tahai [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; Ko Te Riku has restored eyes [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; William Mulloy was an archaeologist [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; William Mulloy is buried at Tahai [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]; Mulloy''s wife is buried at Tahai too [SUPPORTED: https://en.wikipedia.org/wiki/Tahai]"}]'::jsonb),
    ('da102984-38e2-45d9-b411-bb0bbadfb6e1'::uuid, 'card_description', 'At the eastern edge of ancient Archanes on Crete lies Troullos, a Minoan settlement dug first by Sir Arthur Evans, then by Spyridon Marinatos and most recently by J. and E. Sakellarakis.', '1875-1700 BC Minoan settlement - the easternmost section of ancient Archanes. Multi-storey buildings with paved courtyards, light-wells, and ashlar walls mark a sophisticated Bronze Age community.', 'teaser-card-s010-rollback:da102984-38e2-45d9-b411-bb0bbadfb6e1:card_description', 'rollback of teaser-card-s010: card_description ''1875-1700 BC Minoan settlement - the easternmost section of ancient Archanes. Multi-storey buildings with paved courtyards, light-wells, and ashlar walls mark a sophisticated Bronze Age community.'' restored on Troullos', '0e9d93575a2c9e923f3da6b3f239e2b24050a940ab7082563287b7501b7aca5a|6f0f89a2aed5e41e4acec8552256515bc1eead19abea04a0fbfd38b876465508|6f0f89a2aed5e41e4acec8552256515bc1eead19abea04a0fbfd38b876465508', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At the eastern edge of ancient Archanes on Crete lies Troullos, a Minoan settlement dug first by Sir Arthur Evans, then by Spyridon Marinatos and most recently by J. and E. Sakellarakis."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies at the eastern edge of ancient Archanes [S2]; the site is on Crete [S1]; Troullos is a Minoan settlement [S1]; it was first excavated by Sir Arthur Evans [S3]; it was later excavated by Spyridon Marinatos [S3]; it was most recently excavated by J. and E. Sakellarakis [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Troullos is the site of an ancient Minoan settlement on Crete [SUPPORTED: https://en.wikipedia.org/wiki/Troullos]; Troullos lies at the eastern edge of ancient Archanes [SUPPORTED: https://en.wikipedia.org/wiki/Troullos]; Troullos was first excavated by Sir Arthur Evans [SUPPORTED: https://en.wikipedia.org/wiki/Troullos]; Troullos was then excavated by Spyridon Marinatos [SUPPORTED: https://en.wikipedia.org/wiki/Troullos]; Troullos was most recently excavated by J. and E. Sakellarakis [SUPPORTED: https://en.wikipedia.org/wiki/Troullos]; Ancient Archanes was a Minoan settlement on Crete [SUPPORTED: https://en.wikipedia.org/wiki/Archanes]"}]'::jsonb),
    ('da99f5e5-6c0b-4700-a1d1-5f452f06538f'::uuid, 'card_description', 'On the summit of Tops Hill, the 64 stones of Beltany Stone Circle, some more than 6 feet high and several cupmarked, enclose an earthen platform. It dates from around 2100-700 BC.', 'The Beltany stone circle is a Bronze Age stone circle just south of Raphoe town in County Donegal.', 'teaser-card-s010-rollback:da99f5e5-6c0b-4700-a1d1-5f452f06538f:card_description', 'rollback of teaser-card-s010: card_description ''The Beltany stone circle is a Bronze Age stone circle just south of Raphoe town in County Donegal.'' restored on Beltany Stone Circle', '13c1a9d42abadd9ce464ad3a526a2670d2d96eaace0f7c4798ad9cdcb2e3ee55|89df026756507c8e5d85e04796b2bf0eb4f171c039988e5871e995ae38da3178|89df026756507c8e5d85e04796b2bf0eb4f171c039988e5871e995ae38da3178', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the summit of Tops Hill, the 64 stones of Beltany Stone Circle, some more than 6 feet high and several cupmarked, enclose an earthen platform. It dates from around 2100-700 BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the circle is on the summit of Tops Hill [S6]; the circle has 64 stones [S3]; some stones are more than 6 feet high [S4]; several stones are cupmarked [S7]; the stones enclose an earthen platform [S3]; the circle dates from around 2100-700 BC [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Beltany Stone Circle is a stone circle (Bronze Age) at Raphoe, County Donegal, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Beltany_stone_circle]; The circle stands on the summit of Tops Hill [SUPPORTED: https://en.wikipedia.org/wiki/Beltany_stone_circle]; The circle has 64 stones [SUPPORTED: https://en.wikipedia.org/wiki/Beltany_stone_circle]; The 64 stones enclose an earthen platform [SUPPORTED: https://en.wikipedia.org/wiki/Beltany_stone_circle]; Some of the stones are more than 6 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Beltany_stone_circle]; Several of the stones are cupmarked [SUPPORTED: https://en.wikipedia.org/wiki/Beltany_stone_circle]; The circle dates from around 2100-700 BC [SUPPORTED: https://en.wikipedia.org/wiki/Beltany_stone_circle]"}]'::jsonb),
    ('daa573cd-8f9f-4ce7-b141-1652889a2661'::uuid, 'card_description', 'The main altar of the Temple of Apollo at Delphi, the Altar of the Chians is limestone clad in bluish marble slabs, and an inscription on its crowning names its donors: the people of Chios.', 'The 4th century altar was dedicated by the people of Chios, as related on an inscription on the left side of its crowning.', 'teaser-card-s010-rollback:daa573cd-8f9f-4ce7-b141-1652889a2661:card_description', 'rollback of teaser-card-s010: card_description ''The 4th century altar was dedicated by the people of Chios, as related on an inscription on the left side of its crowning.'' restored on Altar of the Chians', 'c3b889ae7bb5bbd5caac7e6128a800a04163eba50babc17a50b036de97060933|95059e3b3907b9e8030c32fe41b88f6a9c98c62b2dd29537e5644b670d95515e|95059e3b3907b9e8030c32fe41b88f6a9c98c62b2dd29537e5644b670d95515e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The main altar of the Temple of Apollo at Delphi, the Altar of the Chians is limestone clad in bluish marble slabs, and an inscription on its crowning names its donors: the people of Chios."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the altar was the main altar of the Temple of Apollo at Delphi [S1]; the altar is made of limestone [S5]; it is clad in slabs of bluish marble [S5]; an inscription on its crowning names the donors [S3]; the donors were the people of Chios [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Altar of the Chians was the main altar of the Temple of Apollo at Delphi, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Altar_of_the_Chians]; The altar has a limestone core [SUPPORTED: https://en.wikipedia.org/wiki/Altar_of_the_Chians]; The limestone is clad in bluish marble slabs [SUPPORTED: https://en.wikipedia.org/wiki/Altar_of_the_Chians]; An inscription on the crowning of the altar names its donors [SUPPORTED: https://en.wikipedia.org/wiki/Altar_of_the_Chians]; The donors of the altar were the people of Chios [SUPPORTED: https://delphi.culture.gr/the-chion-altar/]"}]'::jsonb),
    ('daf2b273-b9a9-4fe9-bd71-b76ff56e7671'::uuid, 'card_description', 'In a dry valley 750m south-east of Avebury, twelve sarsens once formed Falkner''s Circle, about 37 metres across, of which only one still stands; a Mr Falkner found it in 1840 while riding.', 'A stone circle of twelve sarsen megaliths near Avebury, now reduced to a single standing stone. It measured 37 metres across when complete.', 'teaser-card-s010-rollback:daf2b273-b9a9-4fe9-bd71-b76ff56e7671:card_description', 'rollback of teaser-card-s010: card_description ''A stone circle of twelve sarsen megaliths near Avebury, now reduced to a single standing stone. It measured 37 metres across when complete.'' restored on Falkner''s Circle', '8fd60b23e03cb90d5c0d24cc3e92e554589432c5bea949445cef72a30bfa0935|0a5fcac4097017d7ddf2ba6c9e9c42296bb0984d28be3c4ccd3383591ce100ea|0a5fcac4097017d7ddf2ba6c9e9c42296bb0984d28be3c4ccd3383591ce100ea', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In a dry valley 750m south-east of Avebury, twelve sarsens once formed Falkner''s Circle, about 37 metres across, of which only one still stands; a Mr Falkner found it in 1840 while riding."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the circle lies in a dry valley [S4]; it is 750m south-east of Avebury [S8]; the circle was formed of twelve sarsens [S2]; it is no longer complete (once formed) [S1, S2]; the circle was about 37 metres across [S2]; only one stone still stands [S2]; a Mr Falkner found the site in 1840 [S6]; he found it while riding [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Falkner''s Circle was a stone circle near Avebury in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; The circle lay 750m south-east of Avebury [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; The circle lay in a dry valley [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; The circle once had twelve stones (twelve is Falkner''s 1840s count; the 2002 excavation found five stone holes and suggested ten if evenly spaced, but allowed twelve) [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; The stones were sarsens [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; The circle measured about 37 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; Only one of the stones still stands [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; A Mr Falkner found the circle [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; Falkner found it in 1840 [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]; Falkner found it while riding [SUPPORTED: https://en.wikipedia.org/wiki/Falkner%27s_Circle]"}]'::jsonb),
    ('dba260ef-3c25-4731-ac13-7eb55eb3db90'::uuid, 'card_description', 'In 1996 the Glauberg, a basalt spur on the edge of the Wetterau plain, gave up an extremely rare find: a life-sized sandstone statue of an armed warrior from the 5th century BC.', 'A life-size sandstone warrior in a leaf-crown headdress came from a burial mound here — a late Hallstatt princely seat with unprecedented evidence for Celtic sculpture and monumental building.', 'teaser-card-s010-rollback:dba260ef-3c25-4731-ac13-7eb55eb3db90:card_description', 'rollback of teaser-card-s010: card_description ''A life-size sandstone warrior in a leaf-crown headdress came from a burial mound here — a late Hallstatt princely seat with unprecedented evidence for Celtic sculpture and monumental building.'' restored on Glauberg', 'da0580c59dd4dc9c89eb5d3cb9df345250c52d2c0eb014120e563471caf633bc|ca2ec18a747b4efbbf2b8690359e227017709cceb379200f20c4d542a354de0b|ca2ec18a747b4efbbf2b8690359e227017709cceb379200f20c4d542a354de0b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In 1996 the Glauberg, a basalt spur on the edge of the Wetterau plain, gave up an extremely rare find: a life-sized sandstone statue of an armed warrior from the 5th century BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Glauberg is a basalt spur [S1]; it lies on the edge of the Wetterau plain [S1]; in 1996 an extremely rare find was discovered [S7]; the find is a life-sized sandstone statue [S7]; the statue depicts an armed warrior [S8]; the statue dates from the 5th century BC [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Glauberg is a Celtic hillfort or oppidum in Hesse, Germany, with burial mounds [SUPPORTED: https://en.wikipedia.org/wiki/Glauberg]; The Glauberg is a basalt spur on the edge of the Wetterau plain [SUPPORTED: https://en.wikipedia.org/wiki/Glauberg]; The find was made in 1996 [SUPPORTED: https://alm-hessen.de/en/mediathek/der-keltenfuerst-vom-glauberg/]; The 1996 find was extremely rare [SUPPORTED: https://en.wikipedia.org/wiki/Glauberg]; The find is a life-sized sandstone statue [SUPPORTED: https://en.wikipedia.org/wiki/Glauberg]; The statue depicts an armed warrior [SUPPORTED: https://en.wikipedia.org/wiki/Glauberg]; The statue dates from the 5th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Glauberg]"}]'::jsonb),
    ('dbd288ca-6fcc-4eaa-a346-a7b233b33955'::uuid, 'card_description', 'Over time, possibly over several centuries, the dead were laid in the Altendorf Megalithic Tomb, a Late Neolithic gallery grave in northern Hesse. Its bones speak of at least 235-250 people.', 'A Neolithic gallery grave from 3400 BC that contained an unusually large number of burials. Wartberg culture tombs like this were communal ossuaries for whole communities.', 'teaser-card-s010-rollback:dbd288ca-6fcc-4eaa-a346-a7b233b33955:card_description', 'rollback of teaser-card-s010: card_description ''A Neolithic gallery grave from 3400 BC that contained an unusually large number of burials. Wartberg culture tombs like this were communal ossuaries for whole communities.'' restored on Altendorf Megalithic Tomb', '8c2ed60e6acafaaaea70e309d6cc7310dd8d6c59e12786bf46ce2d4ecd220169|8b730f909ebda9e10ddfbf377f440559f6220dbf0672c22f9bd1f07de0df7d61|8b730f909ebda9e10ddfbf377f440559f6220dbf0672c22f9bd1f07de0df7d61', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Over time, possibly over several centuries, the dead were laid in the Altendorf Megalithic Tomb, a Late Neolithic gallery grave in northern Hesse. Its bones speak of at least 235-250 people."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the dead were placed in the tomb over time [S6]; possibly over several centuries [S6]; the tomb is a gallery grave [S2]; it is Late Neolithic [S2]; it is in northern Hesse [S1]; the bones indicate at least 235-250 individuals [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Altendorf Megalithic Tomb is a megalithic gallery grave [SUPPORTED: https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)]; The tomb is Late Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)]; The tomb is in northern Hesse, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)]; The dead were placed in the tomb over time [SUPPORTED: https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)]; The burials possibly spanned several centuries [SUPPORTED: https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)]; The bones indicate 235-250 people [SUPPORTED: https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)]; 235-250 is a minimum (at least) count of individuals [SUPPORTED: https://en.wikipedia.org/wiki/Altendorf_(megalithic_tomb)]"}]'::jsonb),
    ('dc2dad07-a240-4111-9a03-4093ef65301a'::uuid, 'card_description', 'On a volcanic dome in Tlaxcala, the ruins of Xochitecatl cover 12 hectares. Once the centre of a powerful chiefdom, parts of it were reused as a secondary ceremonial centre of Cacaxtla.', 'Active 800 BC–950 AD on a volcanic dome in Tlaxcala, this ceremonial center has Middle Preclassic pyramids. Over 200 female figurines recovered here point to a fertility or goddess-focused cult.', 'teaser-card-s010-rollback:dc2dad07-a240-4111-9a03-4093ef65301a:card_description', 'rollback of teaser-card-s010: card_description ''Active 800 BC–950 AD on a volcanic dome in Tlaxcala, this ceremonial center has Middle Preclassic pyramids. Over 200 female figurines recovered here point to a fertility or goddess-focused cult.'' restored on Xochitecatl', 'aa0ccef012852294894ea451c606c6d8737b1179802f0f47ce8642559104a42d|72b169b79984ea025f5648b8fb1bcfc7f15a3e46b539c3a8c2ed1ef757b67354|72b169b79984ea025f5648b8fb1bcfc7f15a3e46b539c3a8c2ed1ef757b67354', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a volcanic dome in Tlaxcala, the ruins of Xochitecatl cover 12 hectares. Once the centre of a powerful chiefdom, parts of it were reused as a secondary ceremonial centre of Cacaxtla."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the ruins of Xochitecatl stand on a volcanic dome [S3]; the site is in Tlaxcala [S1]; the ruins cover 12 hectares [S3]; Xochitecatl was once the centre of a powerful chiefdom [S4]; parts of the site were reused as a secondary ceremonial centre [S5]; that secondary ceremonial centre belonged to Cacaxtla [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Xochitecatl is an archaeological site (ruins) in the Mexican state of Tlaxcala [SUPPORTED: https://en.wikipedia.org/wiki/Xochitecatl]; The ruins of Xochitecatl are on top of a volcanic dome [SUPPORTED: https://en.wikipedia.org/wiki/Xochitecatl]; The ruins cover 12 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Xochitecatl]; Xochitecatl was once the centre of a powerful chiefdom [SUPPORTED: https://en.wikipedia.org/wiki/Xochitecatl]; Parts of Xochitecatl were later reused as a secondary ceremonial centre [SUPPORTED: https://en.wikipedia.org/wiki/Xochitecatl]; The secondary ceremonial centre was that of Cacaxtla (within its extended urban area) [SUPPORTED: https://en.wikipedia.org/wiki/Xochitecatl]"}]'::jsonb),
    ('dc7253ce-0ab9-43eb-a8ca-a254f77e2d96'::uuid, 'card_description', 'Warawtampu, the high and deep inn of the Pasco Region, was built under Pachakutiq Inka Yupanki. Among its buildings: an Inca house, a woman house and Phaqcha, an altar for water ceremonies.', 'An Inca complex built under Pachakutiq, with buildings named Inkawasi ("Inca house"), Warmiwasi ("Woman house"), and Phaqcha -- an altar for water ceremonies.', 'teaser-card-s010-rollback:dc7253ce-0ab9-43eb-a8ca-a254f77e2d96:card_description', 'rollback of teaser-card-s010: card_description ''An Inca complex built under Pachakutiq, with buildings named Inkawasi ("Inca house"), Warmiwasi ("Woman house"), and Phaqcha -- an altar for water ceremonies.'' restored on Warawtampu', '78cba402594504107e266f47c3e797db4a79be7469739dfe62f9422cd39db9ef|32580903801058c793a97ae25e806e30ac94e6d0a72c33e25c955d01383951ca|32580903801058c793a97ae25e806e30ac94e6d0a72c33e25c955d01383951ca', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Warawtampu, the high and deep inn of the Pasco Region, was built under Pachakutiq Inka Yupanki. Among its buildings: an Inca house, a woman house and Phaqcha, an altar for water ceremonies."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the name Warawtampu means high and deep inn [S1]; the site is in the Pasco Region [S1]; the complex was built under Pachakutiq Inka Yupanki [S4]; its buildings include an ''Inca house'' (Inkawasi) [S5]; its buildings include a ''woman house'' (Warmiwasi) [S5]; its buildings include Phaqcha [S5]; Phaqcha is an altar for water ceremonies [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Warawtampu is an archaeological site in the Pasco Region of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]; The name Warawtampu means high and deep (Quechua waraw) [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]; Warawtampu is an inn (Quechua tampu inn) [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]; The complex was built under Pachakutiq Inka Yupanki [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]; Among its buildings is an Inca house (Inkawasi) [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]; Among its buildings is a woman house (Warmiwasi) [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]; Among its buildings is Phaqcha [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]; Phaqcha is an altar for water ceremonies [SUPPORTED: https://en.wikipedia.org/wiki/Warawtampu]"}]'::jsonb),
    ('dc7674a8-0723-455e-ab0b-9378c4491da9'::uuid, 'card_description', 'On the chalk of Blue Bell Hill in Kent stand tombs of the Medway megaliths, Kit''s Coty House among them. A Neolithic dolmen stood here too, now lost; only fragments of records remain.', 'A chalk hill containing the Medway Megaliths, including Kit''s Coty House. These Neolithic tombs are among the oldest known monuments in southeast Britain.', 'teaser-card-s010-rollback:dc7674a8-0723-455e-ab0b-9378c4491da9:card_description', 'rollback of teaser-card-s010: card_description "A chalk hill containing the Medway Megaliths, including Kit''s Coty House. These Neolithic tombs are among the oldest known monuments in southeast Britain." restored on Blue Bell Hill', '036d277ddc5563b77cab11c3fd07a0805d121ccc14e811a68dd8e5102141563b|3f83250c8fae3a9a218db6ef9871a1840a48a6023ea645b2cd5eaf8a7b0949db|3f83250c8fae3a9a218db6ef9871a1840a48a6023ea645b2cd5eaf8a7b0949db', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the chalk of Blue Bell Hill in Kent stand tombs of the Medway megaliths, Kit''s Coty House among them. A Neolithic dolmen stood here too, now lost; only fragments of records remain."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Blue Bell Hill is a chalk hill [S1]; Blue Bell Hill is in Kent [S1]; tombs of the Medway megaliths stand on the hill [S2]; Kit''s Coty House is among those tombs [S2]; a Neolithic dolmen stood on Blue Bell Hill too [S3, S5]; the dolmen is now lost [S3]; only fragments of records of it remain [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Blue Bell Hill in Kent is a chalk hill (site of prehistoric tombs) [SUPPORTED: https://en.wikipedia.org/wiki/Blue_Bell_Hill]; Tombs of the Medway megaliths stand on Blue Bell Hill [SUPPORTED: https://en.wikipedia.org/wiki/Blue_Bell_Hill]; Kit''s Coty House is among the Medway megalith tombs on the hill [SUPPORTED: https://en.wikipedia.org/wiki/Blue_Bell_Hill]; The lost tomb was a dolmen that stood on Blue Bell Hill [SUPPORTED: https://en.wikipedia.org/wiki/Blue_Bell_Hill]; The dolmen was Neolithic (a Neolithic chamber tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Blue_Bell_Hill]; The dolmen is now lost [SUPPORTED: https://en.wikipedia.org/wiki/Blue_Bell_Hill]; Only fragments of records of the lost dolmen remain [SUPPORTED: https://en.wikipedia.org/wiki/Blue_Bell_Hill]"}]'::jsonb),
    ('dd567577-49dc-45a4-99a9-7beffeb43afe'::uuid, 'card_description', 'In the valley of the River Brue lies the Post Track, a causeway of long ash planks and lime and hazel posts, dated to around 3838 BCE: some 30 years older than the Sweet Track.', 'Built 3838 BC on the Somerset Levels -- about 30 years older than the Sweet Track. Long ash planks on hazel and lime posts at 3-m intervals carried Neolithic travellers across a waterlogged landscape.', 'teaser-card-s010-rollback:dd567577-49dc-45a4-99a9-7beffeb43afe:card_description', 'rollback of teaser-card-s010: card_description ''Built 3838 BC on the Somerset Levels -- about 30 years older than the Sweet Track. Long ash planks on hazel and lime posts at 3-m intervals carried Neolithic travellers across a waterlogged landscape.'' restored on Post Track', '97174be68ee134e8df77fa4c6b7f98c3a92d5f8dccf643e4c5b37534cb3248b3|e13339264f9a9e43dbb94f9f40fbd5206c13030252fa2f5c022cb9910c662f76|e13339264f9a9e43dbb94f9f40fbd5206c13030252fa2f5c022cb9910c662f76', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the valley of the River Brue lies the Post Track, a causeway of long ash planks and lime and hazel posts, dated to around 3838 BCE: some 30 years older than the Sweet Track."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Post Track lies in the valley of the River Brue [S1]; it is a causeway [S1]; it is made of long ash planks [S4]; it has lime and hazel posts [S4]; it is dated to around 3838 BCE [S2]; it is some 30 years older than the Sweet Track [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Post Track is a causeway (a timber trackway) [SUPPORTED: https://en.wikipedia.org/wiki/Post_Track]; It lies in the valley of the River Brue (Somerset Levels) [SUPPORTED: https://en.wikipedia.org/wiki/Post_Track]; It is built of long ash planks [SUPPORTED: https://en.wikipedia.org/wiki/Post_Track]; It has lime and hazel posts [SUPPORTED: https://en.wikipedia.org/wiki/Post_Track]; The Post Track is dated to around 3838 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Post_Track]; It is some 30 years older than the Sweet Track [SUPPORTED: https://www.worldhistory.org/The_Sweet_Track/]"}]'::jsonb),
    ('de46e3ac-0cc0-4466-81aa-0af7a0ac25af'::uuid, 'card_description', 'The walls of Ravenglass Roman Bath House still stand 13 ft high, part of a 2nd-century Roman fort and naval base, with patches of dull red and white rendering and traces of splayed windows.', 'A 2nd-century bath house with walls standing 4 m tall, originally part of a Roman fort. Patches of original pink plaster still cling to the stone.', 'teaser-card-s010-rollback:de46e3ac-0cc0-4466-81aa-0af7a0ac25af:card_description', 'rollback of teaser-card-s010: card_description ''A 2nd-century bath house with walls standing 4 m tall, originally part of a Roman fort. Patches of original pink plaster still cling to the stone.'' restored on Ravenglass Roman Bath House', '3a7b750470abccda044c4dc8b2678de9d2f5ce378b49a9340604dac775f1411e|60720b3633615ce6a3cf42d08193afd9dfc191268779fdd67b4477cb106c5b45|60720b3633615ce6a3cf42d08193afd9dfc191268779fdd67b4477cb106c5b45', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The walls of Ravenglass Roman Bath House still stand 13 ft high, part of a 2nd-century Roman fort and naval base, with patches of dull red and white rendering and traces of splayed windows."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the walls of the bath house still stand [S3]; the walls are 13 ft high [S3]; the bath house is part of (belongs to) a 2nd-century Roman fort and naval base [S2]; patches of dull red and white rendering remain [S3]; traces of splayed windows remain [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ravenglass Roman Bath House is a ruined Roman bath house at Ravenglass [SUPPORTED: https://en.wikipedia.org/wiki/Ravenglass_Roman_Bath_House]; The walls still stand 13 ft high [SUPPORTED: https://en.wikipedia.org/wiki/Ravenglass_Roman_Bath_House]; The bath house belongs to a 2nd-century Roman fort and naval base [SUPPORTED: https://en.wikipedia.org/wiki/Ravenglass_Roman_Bath_House]; The fort at Ravenglass was established around AD 130 (2nd century) [SUPPORTED: https://www.english-heritage.org.uk/visit/places/ravenglass-roman-bath-house/history/]; Ravenglass was a Roman naval base in the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Ravenglass]; There are patches of dull red and white rendering [SUPPORTED: https://en.wikipedia.org/wiki/Ravenglass_Roman_Bath_House]; Traces of splayed windows remain [SUPPORTED: https://en.wikipedia.org/wiki/Ravenglass_Roman_Bath_House]"}]'::jsonb),
    ('dfd872f8-26e9-446d-936e-bdbcd978257a'::uuid, 'card_description', 'Southeast of Dorchester lies Mount Pleasant Henge, an egg-shaped Neolithic enclosure 400 yd long. Its ditch gave up grooved ware and children''s skeletons; its inner henge, many postholes.', 'The enclosure is egg-shaped, measuring 400 yd along its long axis and dates to 2878–2470 cal BC.', 'teaser-card-s010-rollback:dfd872f8-26e9-446d-936e-bdbcd978257a:card_description', 'rollback of teaser-card-s010: card_description ''The enclosure is egg-shaped, measuring 400 yd along its long axis and dates to 2878–2470 cal BC.'' restored on Mount Pleasant Henge', '4bddce2d4bd693a0d3d5bd71e5c796f5bf70a427b30f234a04e6961bb11ae128|dac336799c5d33bff33a76f6a0dc7edf261c9e382b28b5a1fa6156f96ed87e94|dac336799c5d33bff33a76f6a0dc7edf261c9e382b28b5a1fa6156f96ed87e94', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Southeast of Dorchester lies Mount Pleasant Henge, an egg-shaped Neolithic enclosure 400 yd long. Its ditch gave up grooved ware and children''s skeletons; its inner henge, many postholes."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mount Pleasant Henge lies southeast of Dorchester [S2]; it is an egg-shaped enclosure [S3]; it is Neolithic [S1]; it is 400 yd long [S3]; its ditch yielded grooved ware [S5]; its ditch yielded children''s skeletons [S5]; its inner henge held many postholes [S4, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mount Pleasant Henge is a Neolithic henge enclosure (an enclosure/henge, in England, Dorset) [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]; It lies southeast of Dorchester [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]; The enclosure is egg-shaped [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]; The enclosure is 400 yd long [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]; Its ditch yielded grooved ware [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]; Its ditch yielded children''s skeletons [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]; The site has an inner henge [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]; The inner henge contained many postholes [SUPPORTED: https://en.wikipedia.org/wiki/Mount_Pleasant_Henge]"}]'::jsonb),
    ('dff560c6-2128-4e34-b738-e7248403a237'::uuid, 'card_description', 'In the Peruvian coastal desert of the Arequipa region, Toro Muerto holds some 3000 volcanic rocks bearing ancient petroglyphs, a gallery of images beneath the desert sky.', 'Some 3,000 volcanic boulders covered in petroglyphs from the Wari culture, dating to 500-1000 AD. One of the densest concentrations of rock art in the Americas.', 'teaser-card-s010-rollback:dff560c6-2128-4e34-b738-e7248403a237:card_description', 'rollback of teaser-card-s010: card_description ''Some 3,000 volcanic boulders covered in petroglyphs from the Wari culture, dating to 500-1000 AD. One of the densest concentrations of rock art in the Americas.'' restored on Toro Muerto', '5070c52bdad3db6cc26f2412648784a23fb008af9c203159a7f4f3de318f8d15|2e7074a11c64adae35c9d6bbca57ce4af5a1d3f675341d7fed7936b2385d2f46|2e7074a11c64adae35c9d6bbca57ce4af5a1d3f675341d7fed7936b2385d2f46', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the Peruvian coastal desert of the Arequipa region, Toro Muerto holds some 3000 volcanic rocks bearing ancient petroglyphs, a gallery of images beneath the desert sky."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Toro Muerto lies in the Peruvian coastal desert [S1]; it is in the Arequipa region [S1]; it holds some 3000 volcanic rocks [S2]; the rocks bear petroglyphs [S2]; the petroglyphs are ancient [S1]; the petroglyphs form a collection of images in the open desert [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Toro Muerto is a site of ancient petroglyphs (a rock-art site) [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]; Toro Muerto lies in the Peruvian coastal desert [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]; Toro Muerto is in the Arequipa region [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]; The site holds some 3000 rocks [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]; The rocks are volcanic [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]; The rocks bear petroglyphs (images) [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]; The petroglyphs are ancient (Wari culture, active 500 to 1000 AD) [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]; The site is a gallery (collection) of images in the open desert, beneath the sky [SUPPORTED: https://en.wikipedia.org/wiki/Toro_Muerto]"}]'::jsonb),
    ('e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca'::uuid, 'card_description', NULL, 'A Roman fort from the 1st century AD on the Rhine frontier. The river was the empire''s edge — legionaries here watched the border every day for 200 years.', 'teaser-card-s010-rollback:e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca:card_description', 'rollback of teaser-card-s010: card_description "A Roman fort from the 1st century AD on the Rhine frontier. The river was the empire''s edge — legionaries here watched the border every day for 200 years." restored on Alphen aan den Rijn', '||1453ca36f4c4e67ea1436414f8b6c1601f12bf13ed9f0e2d97e59c4fcd6cbc98', '[{"source": "lane WB run wb-ws-2026-09-27-04: contradicted-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The web check could not prove: Alphen aan den Rijn was the site of a Roman fort (castellum Albanianae / Albaniana), remains under the present city centre in the Netherlands; The web check contradicts: That end came in 240 AD (https://www.alphens.nl/nieuws/romeinen-na-het-vertrek.html: \"Met het verlaten van de Nedergermaanse Limes in de Rijndelta rond het jaar 270 komt een einde aan eeuwen van Romeinse overheersing.\")"}]'::jsonb),
    ('e056946d-fd09-43f2-8d45-648121ace99d'::uuid, 'card_description', 'Covered in the 11th century by a castle that later became a prison, the Roman Temple of Vic was spotted in very good condition in 1882, as workers demolished the old castle.', 'An early 2nd-century AD Corinthian temple in Vic — unknown until 1882, having been concealed inside a medieval tower. Fully restored after that tower''s demolition, it stands in the town centre.', 'teaser-card-s010-rollback:e056946d-fd09-43f2-8d45-648121ace99d:card_description', 'rollback of teaser-card-s010: card_description "An early 2nd-century AD Corinthian temple in Vic — unknown until 1882, having been concealed inside a medieval tower. Fully restored after that tower''s demolition, it stands in the town centre." restored on Roman Temple of Vic', '692ab8fa8d580d02e62905a7a67f2099fd70b72445c2b389907c845e1af78f06|6ec2173b360d10c422838e3be3d45e72f698ec1fc1edc775c08e9918a5fd1e91|6ec2173b360d10c422838e3be3d45e72f698ec1fc1edc775c08e9918a5fd1e91', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Covered in the 11th century by a castle that later became a prison, the Roman Temple of Vic was spotted in very good condition in 1882, as workers demolished the old castle."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the temple was covered in the 11th century by a castle [S4]; the castle later became a prison [S4]; the temple was spotted in very good condition [S5]; it was spotted in 1882 [S5]; it was spotted by workers demolishing the old castle [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Temple of Vic is an ancient Roman temple in Vic, Osona, Catalonia, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Vic]; In the 11th century the temple was covered by a castle [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Vic]; The castle later became a prison [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Vic]; The temple was spotted in 1882, during the demolition of the old castle, by workers [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Vic]; The temple was found in very good condition [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Vic]"}]'::jsonb),
    ('e1037d75-2eb6-4076-b28c-86f8159320ab'::uuid, 'card_description', 'On a promontory between the River Dart and the Holy Brook, the Iron Age rampart and ditch of Hembury Castle enclose a later motte, its old ramparts perhaps reused as an outer bailey.', 'Inside the fort, on the western side, is an 11th- or 12th-century motte with a surrounding narrow inner bailey.', 'teaser-card-s010-rollback:e1037d75-2eb6-4076-b28c-86f8159320ab:card_description', 'rollback of teaser-card-s010: card_description ''Inside the fort, on the western side, is an 11th- or 12th-century motte with a surrounding narrow inner bailey.'' restored on Hembury Castle, Buckfast', '345398a046d3593da6dba336b0858c605f6ea66a55d75235b337eda7de543c52|934353ce4fc83ff680784e2ab52ff166022737d64ce28511ea3b337ef79446e5|934353ce4fc83ff680784e2ab52ff166022737d64ce28511ea3b337ef79446e5', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a promontory between the River Dart and the Holy Brook, the Iron Age rampart and ditch of Hembury Castle enclose a later motte, its old ramparts perhaps reused as an outer bailey."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the fort stands on a promontory [S2]; the promontory lies between the River Dart and the Holy Brook [S2]; Hembury Castle has an Iron Age rampart and ditch [S1, S3, S6]; the rampart and ditch enclose a motte [S3, S5]; the motte is later than the hillfort [S5, S6]; the old ramparts may have been reused as the outer bailey [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hembury Castle is an Iron Age hillfort near Buckfast on the edge of Dartmoor, Devon, England, with a later castle motte inside [SUPPORTED: https://en.wikipedia.org/wiki/Hembury_Castle,_Buckfast]; The site lies on a promontory [SUPPORTED: https://en.wikipedia.org/wiki/Hembury_Castle,_Buckfast]; The promontory lies between the River Dart and the Holy Brook [SUPPORTED: https://en.wikipedia.org/wiki/Hembury_Castle,_Buckfast]; The Iron Age fort is surrounded by a rampart and a ditch [SUPPORTED: https://en.wikipedia.org/wiki/Hembury_Castle,_Buckfast]; The rampart and ditch are Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Hembury_Castle,_Buckfast]; Inside the fort stands a later motte (11th- or 12th-century) [SUPPORTED: https://en.wikipedia.org/wiki/Hembury_Castle,_Buckfast]; The old hillfort ramparts were perhaps reused as the outer bailey of the castle [SUPPORTED: https://en.wikipedia.org/wiki/Hembury_Castle,_Buckfast]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s010-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s010-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s010-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('a627df4e-f241-478e-b8ab-273e67f52441'::uuid, 'card_description', 'Oak planks laid end-to-end on crossed pegs of ash, oak and lime: the Sweet Track, built in 3807 or 3806 BC across a Somerset marsh, was used for only around ten years, then abandoned.'), ('a692e959-c6b4-45b5-96f6-65b82c883a35'::uuid, 'card_description', NULL), ('a6d5b07a-c9ea-4e5a-a82d-4416a045f1bc'::uuid, 'card_description', 'Between Tjörnarp and Sösdala lies the Vätteryd Grave Field, an Iron Age burial ground that gave up bronze jewelry, glass and bronze pearls, silver threads and silver bands.'), ('a6f66111-c0d1-4c01-a49a-eb2d476a33d0'::uuid, 'card_description', 'Built from the booty of battles against Athens, the Treasury of the Acanthians rose at Delphi. Plutarch records its dedication: Brasidas and the Acanthians from the Athenians.'), ('a7afa2f1-87c5-4fa8-ab8f-0e86d714a8f8'::uuid, 'card_description', 'On the west side of the Fosse Way lies Dorn, where a small Roman town once stood: the largest of five defended small towns strung along its line between Cirencester and Lincoln.'), ('a7ce791d-67cb-4895-bb89-00d4f1dd868b'::uuid, 'card_description', 'In a valley near Taxila, the Buddhist monastery of Mohra Muradu set 27 rooms around a courtyard with a pool for ritual washings, and statues of Buddha were found there in abundance.'), ('a9a3d2fe-0f58-4627-a34d-124e0190d7e8'::uuid, 'card_description', 'Named for the many bats in the caves of nearby cliffs, the Maya site of El Zotz appears to have peaked for only about one hundred years, in an intense burst of building palaces and pyramids.'), ('aaa12d23-d666-4a40-9f3c-17d861f4e143'::uuid, 'card_description', 'Lance-bearers, ritual dances, camel caravans, the sun and other stars: quarry workers stumbled on the Gobustan Rock Art in the 1930s, engravings from prehistoric to medieval times.'), ('ab20e4ad-f101-4b3d-84fb-c0710060c941'::uuid, 'card_description', 'Outside the entrance of the Stonehenge earthwork, the Heel Stone, a single sarsen weighing about 35 tons, leans nearly 27 degrees from the vertical, with a further 1.2 metres buried below.'), ('ab524e5e-2c34-4564-ab3a-f7ab487116f4'::uuid, 'card_description', 'In 1932 a collapse during the renovation of homes in Minori opened an underground chamber of the Villa Romana, a Roman villa of the 1st century on a bay where the Regina Minor meets the sea.'), ('ab6ffb1d-c6d2-4c14-96e8-7f76a2607d7d'::uuid, 'card_description', 'On the north coast of Crete, Amnisos was a Bronze Age port to the palace city of Knossos. The sea now stands three meters higher, and walls of submerged houses can be seen from the shore.'), ('ac3877a0-04fc-4049-b918-ebf41b0a1501'::uuid, 'card_description', 'The dry desert kept the Cerro Pátapo Ruins remarkably well preserved: a Wari city near Chiclayo with special spots set aside for human sacrifice and a pile of bones at the foot of a cliff.'), ('ac46cdfd-877f-47d4-8403-90d21983364f'::uuid, 'card_description', 'Once called Cecropia after the legendary serpent-man Cecrops, the Acropolis of Athens rises on a rocky outcrop where Pericles coordinated the building of the Parthenon and the Erechtheion.'), ('aceee58f-9865-4095-8bff-bef66f5baa73'::uuid, 'card_description', 'Large polychrome figures are a striking feature of Mojeque in northern Peru, whose main mound is a stepped pyramid of at least six platforms, about 30 m in height and almost quadrangular.'), ('addfeb62-4424-4c58-8a2a-0c5e26a98df9'::uuid, 'card_description', 'Mosaics with geometrical and naturalistic motifs adorn the main rooms of the Roman Ruins of Pisões, a farming villa that supplied Pax Julia with foodstuffs, watered from a nearby Roman dam.'), ('ae2ca7b1-89da-46cb-8924-f9d04dd5da2e'::uuid, 'card_description', 'At Banias a spring once associated with the god Pan rose from a large cave in a sheer cliff, gradually lined with shrines. It is the source of a main tributary of the Jordan River.'), ('ae2d2c32-689c-443f-ba05-e70023619136'::uuid, 'card_description', 'At the heart of the Bronze Age palace of Knossos lies the Throne Room, a ceremonial chamber of the 15th century BC with gypsum benches on three sides, unearthed by Arthur Evans in 1900.'), ('ae519f45-f80c-4464-8f76-e9d986803c34'::uuid, 'card_description', 'On Anglesey, two quartz-rich boulders about 4.1 and 3 metres high appear to stand in their original positions, a slab between them read as the former capstone of Henblas Burial Chamber.'), ('b0c061fd-8644-433e-a61c-9b20fd960c26'::uuid, 'card_description', 'On Lake Neuchâtel''s northern shore lies La Tène, the type site of the La Tène culture. Around 1870 the lake fell 2.7 m, and a site believed to be exhausted proved to have more to be found.'), ('b1e7b190-e66c-49da-8df8-2b1345fa68fd'::uuid, 'card_description', 'Near Lake Titicaca, Tiwanaku once spanned roughly 4 square kilometers. Digging into its terraced platform mound, the Akapana, revealed sacrificial dedications of humans and camelids.'), ('b2a9c061-0761-4f66-9406-130bf68f6770'::uuid, 'card_description', 'Two concentric ramparts up to 5.8 metres high ring Warbstow Bury, an Iron Age hillfort in Cornwall. At its centre lies a medieval rabbit warren known as the Giant''s Grave.'), ('b2b1beee-00c6-4dfa-a616-89f7be1b86b7'::uuid, 'card_description', 'Investigating looting in 1990, an archaeologist at Balamkú found a trench that had partly bared a painted Maya stucco frieze, 16.8 metres long, joining rulers with a sacred mountain.'), ('b306aff1-60d0-4d34-85e3-fe206911dc65'::uuid, 'card_description', 'Shipton Hill Settlement is a rare Iron Age defended settlement in Dorset, a type occupied by small communities, perhaps a single family group. Partial excavation found hammer stones.'), ('b3528337-0230-4210-a01c-dadd353b879e'::uuid, 'card_description', 'Coney''s Castle, an Iron Age hillfort in Dorset, rides a narrow ridge reaching 210 m, a small lane cutting through it. Its name, from Old English for rabbit, hints at a medieval warren.'), ('b367310b-a211-40b3-b376-80e9da0fdd32'::uuid, 'card_description', 'On the island of Orust, four raised stone slabs hold up a fifth as a roof: the Haga Dolmen, small in size yet with the province''s largest inside chamber, roughly dated to about 3400 BCE.'), ('b5899722-5118-41e0-8324-5da705ace4a2'::uuid, 'card_description', 'South of Portbury near Bristol lies Conygar Hillfort, a small multivallate Iron Age fort of triangular shape, where the remains of a bank 3 feet high mark the south-western side.'), ('b596bc7e-15ff-4dfd-b052-710626210123'::uuid, 'card_description', 'On a small hill near Rovinj, Monkodonja was ringed by three concentric dry stone walls of Cyclopean masonry reminiscent of Mycenean work, and Bronze Age cist graves lay in its western gate.'), ('b60c114a-7ee2-4f67-b3ff-a3d3d3e55d15'::uuid, 'card_description', 'At Billingsgate Roman House and Baths in Londinium, a bath with hypocausts survives best. Digs found several hundred late 4th century coins and, in fallen roof debris, an Anglo-Saxon brooch.'), ('b672af27-ee37-4815-bd7c-f1a5e09f2413'::uuid, 'card_description', 'Building an underpass in Plovdiv uncovered the Domus Eirene, a Roman peristyle house whose lavish mosaic floors show endless knots, flowers and inscriptions welcoming visitors.'), ('b6aab229-8793-40ad-a697-c8dbf6e331bf'::uuid, 'card_description', 'Within the ramparts of Grovely Castle, an Iron Age hill fort in Wiltshire, excavations uncovered five human skeletons, while aerial photographs reveal a circular enclosure in its interior.'), ('b774f9cc-ea01-4658-b12c-c66add4453d1'::uuid, 'card_description', 'Below the crest of Copehill Down lies White Barrow, a Neolithic long barrow never fully excavated. A 1997 survey found evidence of a possible burial chamber inside, and an arc of post pits.'), ('b8583e63-17c5-48b0-a4d1-018acaf608c1'::uuid, 'card_description', 'Iron Age Meare Lake Village was raised over a morass on timber, brushwood and clay. Its ruins gave up red deer antler, a spiral finger ring of bronze and a decorated amber bead.'), ('ba0866bd-4186-4722-8e4d-ea67e228062b'::uuid, 'card_description', 'Copper was mined at Apliki from the late 14th Century BC. On its rocky terraces stood a smelter site, and four houses gave up an ivory cylinder, a steatite seal and a gold earring.'), ('bb263810-ca13-4ab1-b97d-d5ce2b2d0ab3'::uuid, 'card_description', 'They call it the Lost City of Huayuri: ruins stretching about 500 metres along a ravine between two ridges, where rainfall harvesting began between 1260 and 1290 CE.'), ('bbe632de-a422-458f-8379-bef7ed34d4ef'::uuid, 'card_description', 'Bulls-eye shaped ceremonial buildings rise on the hill slopes of Los Guachimontones, in number and size by far the largest of several dozen Teuchitlán Culture sites in the Tequila Valleys.'), ('bc28c81f-db22-46a5-bc4e-18cb8c2ecbec'::uuid, 'card_description', 'Deep in the jungles of Campeche, Structure 2 of Calakmul rises over 45 metres. This Maya city rivalled Tikal throughout the Classic period and lost to it in a decisive battle in AD 695.'), ('bcf13ede-0f30-415a-85ea-59bfd6d4cce4'::uuid, 'card_description', 'Named after Mars, Roman god of war, the garrison of Castra Martis guarded the road through the Vrashka Chuka pass. In 408 the Huns under Uldin took it, apparently by treachery.'), ('bd3f6a4e-0452-448a-8674-b8a87c0e63e8'::uuid, 'card_description', 'In the limestone of Magura Cave, prehistoric painters left hunting scenes, religious ceremonies and deities, among them the Fertility Dance and the Hunting Ceremony.'), ('bdbf1e68-32c8-4571-90c0-ef154d458704'::uuid, 'card_description', 'On the Franklin River in Tasmania lies Kutikina Cave, the most southerly human occupation in the world during the last ice age, with evidence of wallaby hunting on open tundra.'), ('be81c1a6-cd42-4fea-8bb9-323bf0a1c586'::uuid, 'card_description', 'Three of the six Baalbek Stones form the Trilithon in a temple podium wall: Roman blocks each 19 metres long and around 750–800 tonnes, a gigantism unparalleled in antiquity.'), ('bf43132d-1cbc-4dd2-9cf9-914a917e78d9'::uuid, 'card_description', 'High on a mountain named Coyor, about 2,970 metres up and east of Lake San Nicolas, lies Collor, an archaeological site whose name may come from the Quechua word for star.'), ('c070b6b0-3fd2-4d6c-acbe-105539188253'::uuid, 'card_description', 'Around 480,000 years ago, early humans hunted and butchered here: Eartham Pit, Boxgrove, one of the oldest sites in Europe with direct evidence of both, now some 10 kilometres inland.'), ('c08d8ce8-6103-4f32-bb80-9e59c0a97a17'::uuid, 'card_description', 'Paleolithic people once lived in Buzeyir Cave, where digs unearthed items of stone and sharpened animal bones. Found in 1985, it has yielded around 74 artefacts.'), ('c1448f84-e07a-436a-8110-087f293a6564'::uuid, 'card_description', 'West-southwest of Hanover, right on the city boundary, the Benther Berg ridge climbs to 173.3 m above sea level. On it lie protohistorical tumuli from the Bronze Age.'), ('c2cd2a6a-8f1d-4fce-9645-234908ef7d37'::uuid, 'card_description', 'Hodson Stone Circle once stood in Wiltshire; in the 1890s A. D. Passmore recorded eight stones and a possible avenue. Some of the village''s building sarsens were once part of the ring.'), ('c3bf5c7e-26d4-4441-95ea-990a5c82c4ae'::uuid, 'card_description', 'Brown road signs guide you 310 kilometres from Osnabrück to Oldenburg along the Route of Megalithic Culture, to standing stones and the lives of people who lived over 5,000 years ago.'), ('c5851dba-f3f4-4aaf-a4a1-37bf6a56600b'::uuid, 'card_description', 'For many centuries the trees of Micheldever Wood have preserved features from the Bronze Age to the Romano-British period, among them a cross dyke thought to mark a territorial boundary.'), ('c5a5ae3a-46fd-45e6-8d02-45abfdee24aa'::uuid, 'card_description', 'Northeast of Patras, 220 meters up, the Mycenaean Cemetery of Voudeni keeps 78 carved tombs, many domed, often with multiple burials, each yielding vases, jewellery, tools or weapons.'), ('c5c4cc93-5ab1-40f1-8b8f-b42255fea0c5'::uuid, 'card_description', 'Sanctuary of Angitia, a goddess venerated by the Marsi, Lucus Angitiae reveals two temples, an Italic one of two cellas and a Roman one of three rooms, among Doric columns and burials.'), ('c5c5f2da-a5ea-41c6-807d-4c8ad7af03ba'::uuid, 'card_description', 'Found in the River Witham in 1826, the Witham Shield is Iron Age bronze of La Tène style. Small rivet holes and stains hint at a long-legged leather wild boar once riveted to its face.'), ('c5d612d7-5604-4de3-b797-7cbcbdafdde7'::uuid, 'card_description', 'At the foot of Guanyin Mountain, near the mouth of the Tamsui River, the Shihsanhang Museum of Archaeology keeps the finds of an Iron Age site that gave up over 300 skeletons.'), ('c66b25a2-35e6-4d6f-a8bb-683a473f86ca'::uuid, 'card_description', 'On the plain of Leivithra lies Kompoloi, an ancient winery of 17 rooms built on a vineyard. Its wine was stored in 32 clay pithoi buried in the ground, until a fire destroyed the building.'), ('c70fe2a7-a7d0-4b6e-b59d-b4d1510573bf'::uuid, 'card_description', 'In the Huanta District of Peru''s Ayacucho Region lies Pusuquy Pata, its Ayacucho Quechua name joining a cactus and a river bank: a site of tombs left by the Wari culture.'), ('c75b6409-59b2-4675-a402-796d4b2ba6fb'::uuid, 'card_description', 'In west Donegal, low land prominent for its court and portal tombs, the smaller portal tomb of Kilclooney More rests in a shallow basin north of the Abberachrin River, one portal stone gone.'), ('c86e3d9b-38c0-478a-8d06-e91f90c2859d'::uuid, 'card_description', 'At the Pocklington Iron Age Burial Ground, a warrior lay on his shield, the first shield burial found in Britain, while another was pierced by five spears beside a broken sword.'), ('c9066b1a-0da8-436f-ad87-cdec31e99366'::uuid, 'card_description', 'San Pawl Milqi, ruins of a Roman period villa and pagan temple, lay near the Roman harbour at Salina, ideally suited to olive oil. One burial there bears a neo-Punic inscription.'), ('c9755577-6815-411d-bb1e-f96330776818'::uuid, 'card_description', 'Its Roman name has not survived; the Middle Ages named it the Porta Nigra for its darkened stone. Sole survivor of Trier''s four Roman city gates, it later housed a Greek monk as a hermit.'), ('c99e3f1e-85ab-47d3-ac5c-2f50e896417d'::uuid, 'card_description', 'Inside the Piscina Mirabilis, the wondrous pool, four rows of twelve cruciform pillars fill a Roman cistern 15 metres high and 72 metres long, built to hold 12.6 million litres of water.'), ('ca28f10c-b6b6-41bb-bf64-980908425ab7'::uuid, 'card_description', 'Unearthed in 1998 at Nekresi in Kakheti, the ruined Chabukauri Basilica of large limestone blocks, dated to the 4th or 5th century, is one of the earliest Christian churches in Georgia.'), ('cb0a55c2-48c5-4340-afb2-a5c0d5eec70b'::uuid, 'card_description', 'Ptolemy knew Dzalisi as Zalissa, a principal town of Iberia. Digs revealed four palaces, a swimming pool and a mosaic of Ariadne and Dionysus at a banquet, among the oldest in the Caucasus.'), ('cb659fbe-0f1c-43dc-9c40-4517c0974a79'::uuid, 'card_description', 'Hot mineral springs at a bend in the Limmat drew the Romans to Aquae Helveticae. Burned by a legion in 69 AD and rebuilt in stone, much of it now lies beneath the town of Baden.'), ('cb9eb967-f8ee-4c08-98f5-c2a0a181bc81'::uuid, 'card_description', 'Between St Cleer and Darite in Cornwall stands Trethevy Quoit, a well-preserved megalith. Its type was raised between 3700 and 3500 BC, perhaps as a religious structure or community grave.'), ('cbc9996e-862d-44dd-b6be-c2967bc3f58c'::uuid, 'card_description', 'In Split, an emperor''s mausoleum became the Cathedral of Saint Domnius. Its niches once held statues of gods and emperors, and two medallions are identified as Diocletian and Prisca.'), ('cbe321a4-0b00-4c6e-9773-f006757e637a'::uuid, 'card_description', 'Beneath the modern A417, A419 and B4000 runs much of Ermin Way, a Roman road that linked Glevum and Corinium to Calleva, where it met the Devil''s Highway to Londinium.'), ('ccb5fcce-35d3-463a-bb98-0cfc09918465'::uuid, 'card_description', 'The Castro of Cidadelhe crowns an isolated rural hilltop in Mesão Frio: a fortified settlement of a proto-historic nature, later occupied by Roman and Medieval residents.'), ('ccf92317-4881-4850-a573-4ccd961772d5'::uuid, 'card_description', 'Between Avebury and Stonehenge lies Marden Henge, the largest Neolithic henge found to date in the United Kingdom, where a 1776 record told of a mound approximately 30 feet tall.'), ('cd7f64d3-c693-4955-88e3-638fbea42afd'::uuid, 'card_description', 'Near Lynmouth, Wind Hill rises to 261 metres between the steep valley of the East Lyn River and the cliffs, its spur defended by the enormous earthworks of an Iron Age hill fort.'), ('ce033c02-864e-45aa-8b32-f233dda3e043'::uuid, 'card_description', 'Ranigat means Queen''s Rock, after a rock on top of a mountain visible from far away. Along its ridge lie the remains of the region''s largest Buddhist monastic complex.'), ('ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb'::uuid, 'card_description', 'The Tayma Stones are more than 130 Achaemenid-era Aramaic inscriptions, many from approximately the 5th and 6th centuries BCE. In 1878 Charles Huber saw the steles still in place.'), ('ceee8f24-5956-418d-b668-7f3e3e56a3f6'::uuid, 'card_description', 'On a hill above the Vardar River, the ruins at Isar, Marvinci are believed to be Idomenae, a fortified Macedonian town first recorded in the 5th century BC that later became a Roman city.'), ('cfb36f32-10c1-477e-8a10-203dea937c00'::uuid, 'card_description', 'At about 4,433 metres in the Pasco Region, Kuntuyuq keeps its rock paintings on a mountain of the same name that rises up to 4,475 metres, north-west of the lake Allqaqucha.'), ('d2b71745-bf32-4027-8920-18fcd5600c8d'::uuid, 'card_description', 'Southeast of Cusco, three Inca canals divert the Pukara river across Tipón, one flowing on top of an intact stone aqueduct, on a site continuously occupied from around 1000 BCE.'), ('d2b862c0-44e2-422f-9c17-5548b3c74a7f'::uuid, 'card_description', 'Rediscovered in November 1947 as a housing estate went up, Kings Weston Roman Villa retains its original mosaic floors, a hypocaust and the only Roman bath suite visible in Bristol.'), ('d5a5f6ff-a9cd-424e-9af9-572b0844f980'::uuid, 'card_description', 'Timpone della Motta, a hill in Calabria inhabited since the Middle Bronze Age, became the acropolis and sanctuary of Greek colonists from Sybaris. Thousands of hydriskai were found there.'), ('d6a95fc5-ad9c-4181-b04b-e57b8b0088da'::uuid, 'card_description', 'The Archaeological Park of Dion at Mount Olympus holds sanctuaries, bathhouses, shops and workshops. Here Alexander the Great sacrificed to Zeus before his campaign against the Persians.'), ('d6bc5056-b3e5-4038-86f4-cdb08090202a'::uuid, 'card_description', 'On a hilltop in Warren Wood, approximately 90 metres above sea level, Wasteberry Camp looks out over Silverbridge Lake: an Iron Age hill fort near the hamlet of Blackpool, Devon.'), ('d78800a3-e78d-4c72-90b0-069140ad9b02'::uuid, 'card_description', 'On the plain of Amari lies Monastiraki, a Minoan town never built on after its destruction, where storehouses, sanctuaries and two archive rooms of earthenware stamps have come to light.'), ('d7c375d0-6ddc-42ed-a3d4-f128c3c1d89f'::uuid, 'card_description', 'In 1954, while Sylt Airport was under development, the stones of the Harhoog were moved to the coast near Keitum: a Funnelbeaker dolmen whose graves probably date to around 3000 BC.'), ('d82e4a95-00dd-4c1d-8e94-dd201f72e331'::uuid, 'card_description', 'On a cliff in the Gersac valley, La Chaire a Calvin bears a sculpted Magdalenian frieze: an aurochs without its head, a pregnant tarpan and mating tarpans, approximately 15000 years BP.'), ('d8af7833-8171-40a3-a24c-cd3fff898c07'::uuid, 'card_description', 'At Karnak, the Temple of Ptah has six small gateways built close together; the sixth runs directly into the central sanctuary, where the statue of Ptah stands. Baboon figurines were found.'), ('d8c32771-f319-4432-9333-aa646e273001'::uuid, 'card_description', 'On a hill 450 m above sea level, the Illyrian town of Dimale was walled around the mid-4th century BC and later gained stoas, a temple and a theater. Tiles stamped DIMALLITAN identified it.'), ('d8d9d536-918c-461f-a05f-4080c8660afa'::uuid, 'card_description', 'Around 4,000 years ago Neolithic settlers came to the Niumatou Site, the oldest in central Taiwan. They left pottery and so many stone hoes that they probably relied largely on farming.'), ('d9023096-4bef-47a7-bcb4-2e3f4cf0ba36'::uuid, 'card_description', 'Near a Roman aqueduct in Amadora lies the Roman Villa of Quinta da Bolacha, built during the Roman occupation of the Iberian peninsula and occupied in the 3rd and 4th century.'), ('d972a5b7-866c-48d6-af54-d9ac91f00b0b'::uuid, 'card_description', 'On Rapa Nui, three principal ahu run north to south at the Tahai Ceremonial Complex, Ko Te Riku with its restored eyes. Archaeologist William Mulloy and his wife are buried here.'), ('da102984-38e2-45d9-b411-bb0bbadfb6e1'::uuid, 'card_description', 'At the eastern edge of ancient Archanes on Crete lies Troullos, a Minoan settlement dug first by Sir Arthur Evans, then by Spyridon Marinatos and most recently by J. and E. Sakellarakis.'), ('da99f5e5-6c0b-4700-a1d1-5f452f06538f'::uuid, 'card_description', 'On the summit of Tops Hill, the 64 stones of Beltany Stone Circle, some more than 6 feet high and several cupmarked, enclose an earthen platform. It dates from around 2100-700 BC.'), ('daa573cd-8f9f-4ce7-b141-1652889a2661'::uuid, 'card_description', 'The main altar of the Temple of Apollo at Delphi, the Altar of the Chians is limestone clad in bluish marble slabs, and an inscription on its crowning names its donors: the people of Chios.'), ('daf2b273-b9a9-4fe9-bd71-b76ff56e7671'::uuid, 'card_description', 'In a dry valley 750m south-east of Avebury, twelve sarsens once formed Falkner''s Circle, about 37 metres across, of which only one still stands; a Mr Falkner found it in 1840 while riding.'), ('dba260ef-3c25-4731-ac13-7eb55eb3db90'::uuid, 'card_description', 'In 1996 the Glauberg, a basalt spur on the edge of the Wetterau plain, gave up an extremely rare find: a life-sized sandstone statue of an armed warrior from the 5th century BC.'), ('dbd288ca-6fcc-4eaa-a346-a7b233b33955'::uuid, 'card_description', 'Over time, possibly over several centuries, the dead were laid in the Altendorf Megalithic Tomb, a Late Neolithic gallery grave in northern Hesse. Its bones speak of at least 235-250 people.'), ('dc2dad07-a240-4111-9a03-4093ef65301a'::uuid, 'card_description', 'On a volcanic dome in Tlaxcala, the ruins of Xochitecatl cover 12 hectares. Once the centre of a powerful chiefdom, parts of it were reused as a secondary ceremonial centre of Cacaxtla.'), ('dc7253ce-0ab9-43eb-a8ca-a254f77e2d96'::uuid, 'card_description', 'Warawtampu, the high and deep inn of the Pasco Region, was built under Pachakutiq Inka Yupanki. Among its buildings: an Inca house, a woman house and Phaqcha, an altar for water ceremonies.'), ('dc7674a8-0723-455e-ab0b-9378c4491da9'::uuid, 'card_description', 'On the chalk of Blue Bell Hill in Kent stand tombs of the Medway megaliths, Kit''s Coty House among them. A Neolithic dolmen stood here too, now lost; only fragments of records remain.'), ('dd567577-49dc-45a4-99a9-7beffeb43afe'::uuid, 'card_description', 'In the valley of the River Brue lies the Post Track, a causeway of long ash planks and lime and hazel posts, dated to around 3838 BCE: some 30 years older than the Sweet Track.'), ('de46e3ac-0cc0-4466-81aa-0af7a0ac25af'::uuid, 'card_description', 'The walls of Ravenglass Roman Bath House still stand 13 ft high, part of a 2nd-century Roman fort and naval base, with patches of dull red and white rendering and traces of splayed windows.'), ('dfd872f8-26e9-446d-936e-bdbcd978257a'::uuid, 'card_description', 'Southeast of Dorchester lies Mount Pleasant Henge, an egg-shaped Neolithic enclosure 400 yd long. Its ditch gave up grooved ware and children''s skeletons; its inner henge, many postholes.'), ('dff560c6-2128-4e34-b738-e7248403a237'::uuid, 'card_description', 'In the Peruvian coastal desert of the Arequipa region, Toro Muerto holds some 3000 volcanic rocks bearing ancient petroglyphs, a gallery of images beneath the desert sky.'), ('e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca'::uuid, 'card_description', NULL), ('e056946d-fd09-43f2-8d45-648121ace99d'::uuid, 'card_description', 'Covered in the 11th century by a castle that later became a prison, the Roman Temple of Vic was spotted in very good condition in 1882, as workers demolished the old castle.'), ('e1037d75-2eb6-4076-b28c-86f8159320ab'::uuid, 'card_description', 'On a promontory between the River Dart and the Holy Brook, the Iron Age rampart and ditch of Hembury Castle enclose a later motte, its old ramparts perhaps reused as an outer bailey.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s010-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
